insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c6000000-0000-0000-0000-000000000001', 'ukmla', 'f276282b-2cd4-4681-a37c-53ff7fa28242',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c6000000-0000-0000-0000-000000000001', 'A', 'Stop warfarin permanently and discharge home', false, 'Ruled out because warfarin should not simply be stopped and the patient discharged while actively bleeding; the anticoagulation status is relevant to overall management but the immediate priority is controlling the haemorrhage, with anticoagulation reviewed alongside haematology/medical advice.', 1),
('c6000000-0000-0000-0000-000000000001', 'B', 'Arrange outpatient ENT review in two weeks', false, 'Ruled out because this is an active bleed that has already failed simple first aid; it needs immediate management, not deferred outpatient review.', 2),
('c6000000-0000-0000-0000-000000000001', 'C', 'Reassure and repeat pinching the bony bridge of the nose for a further 20 minutes', false, $x$Ruled out because pressure should be applied to the soft cartilaginous (Little's area) part of the nose, not the bony bridge, and prolonged repetition of a failed technique delays definitive treatment.$x$, 3),
('c6000000-0000-0000-0000-000000000001', 'D', 'Anterior nasal packing after examining for a visible bleeding point', true, 'Correct. First aid measures (sitting forward, firm pressure on the cartilaginous part of the nose for at least 10-15 minutes) have failed, so the next step is to examine the nose with good lighting/suction for a visible bleeding point (for cautery if seen) and, if bleeding persists or no point is visible, to pack the nose anteriorly.', 4),
('c6000000-0000-0000-0000-000000000001', 'E', 'Perform immediate surgical ligation of the sphenopalatine artery', false, 'Ruled out because surgical or endoscopic arterial ligation is reserved for bleeding refractory to packing and other first-line measures, not the immediate next step after first aid alone has failed.', 5),
('c6000000-0000-0000-0000-000000000002', 'A', 'Perform a blind finger sweep of the oropharynx to remove the foreign body', false, 'Ruled out because blind finger sweeps risk pushing the foreign body further into the airway and causing further obstruction or trauma, and are not part of the recommended choking algorithm.', 1),
('c6000000-0000-0000-0000-000000000002', 'B', 'Reassure the child and observe for spontaneous resolution over the next hour', false, 'Ruled out because this represents severe obstruction with hypoxia and an ineffective cough, which requires immediate active intervention, not watchful waiting.', 2),
('c6000000-0000-0000-0000-000000000002', 'C', 'Perform an emergency needle cricothyroidotomy immediately', false, 'Ruled out because cricothyroidotomy is a last resort for complete obstruction where less invasive measures (back blows, thrusts, direct laryngoscopy/removal) have failed and the child has become unconscious; it is not the first step in a conscious child.', 3),
('c6000000-0000-0000-0000-000000000002', 'D', 'Give high-dose nebulised salbutamol and oral dexamethasone', false, 'Ruled out because this presentation is due to foreign body aspiration, not asthma or croup, so bronchodilators and steroids will not relieve the mechanical obstruction.', 4),
('c6000000-0000-0000-0000-000000000002', 'E', 'Call for immediate senior/anaesthetic and ENT help while giving up to 5 back blows', true, 'Correct. This is severe airway obstruction with an ineffective cough (unable to speak/cry normally, cyanosis risk, quiet or absent cough) in a conscious child; paediatric choking algorithm indicates up to 5 back blows (followed by abdominal/chest thrusts if unsuccessful) while urgently summoning senior anaesthetic/ENT support for a potentially compromised airway.', 5),
('c6000000-0000-0000-0000-000000000003', 'A', 'Perform a direct examination of the oropharynx with a tongue depressor to visualise the epiglottis', false, 'Ruled out because instrumenting or distressing the airway in suspected epiglottitis can precipitate complete airway obstruction; the oropharynx should not be examined outside a controlled setting with airway support available.', 1),
('c6000000-0000-0000-0000-000000000003', 'B', 'Keep the child calm with the parent, avoid examining the throat, and urgently call anaesthetics and ENT for airway assessment', true, 'Correct. This clinical picture (unvaccinated child, rapid onset fever, drooling, tripod positioning, muffled voice, stridor) is classic for acute epiglottitis, a life-threatening airway emergency. The priority is to avoid distressing the child or examining the oropharynx (which can precipitate complete obstruction) and to urgently involve senior anaesthetic and ENT teams to secure the airway in a controlled setting.', 2),
('c6000000-0000-0000-0000-000000000003', 'C', 'Give oral amoxicillin and discharge with safety-net advice', false, 'Ruled out because suspected epiglottitis is a medical emergency requiring urgent hospital assessment and airway management, not outpatient oral antibiotics and discharge.', 3),
('c6000000-0000-0000-0000-000000000003', 'D', 'Lay the child flat and attempt to pass a nasogastric tube for feeding', false, 'Ruled out because forcing a child with suspected epiglottitis to lie flat or instrumenting the airway can worsen obstruction; the child should be allowed to sit in the position of comfort.', 4),
('c6000000-0000-0000-0000-000000000003', 'E', 'Perform urgent flexible nasendoscopy in the emergency department by the on-call doctor', false, 'Ruled out because any airway instrumentation in suspected epiglottitis should occur in a controlled environment (theatre) with anaesthetic and ENT support present, not as an unsupervised bedside procedure.', 5),
('c6000000-0000-0000-0000-000000000004', 'A', 'Peritonsillar abscess (quinsy)', true, 'Correct. Unilateral soft palate swelling with contralateral uvular deviation, trismus, muffled voice, and odynophagia following a preceding tonsillitis is the classic picture of a peritonsillar abscess (quinsy), which requires urgent ENT assessment for needle aspiration or incision and drainage plus IV antibiotics.', 1),
('c6000000-0000-0000-0000-000000000004', 'B', 'Simple acute tonsillitis', false, 'Ruled out because simple tonsillitis does not cause unilateral palatal swelling, uvular deviation, or trismus; these features indicate a collection of pus (abscess) beyond the tonsillar capsule.', 2),
('c6000000-0000-0000-0000-000000000004', 'C', 'Infectious mononucleosis', false, 'Ruled out because although glandular fever can cause severe tonsillitis and lymphadenopathy, it does not typically cause unilateral peritonsillar swelling with uvular deviation and trismus.', 3),
('c6000000-0000-0000-0000-000000000004', 'D', 'Retropharyngeal abscess', false, 'Ruled out because retropharyngeal abscess typically presents with midline posterior pharyngeal wall swelling, neck stiffness, and is more common in younger children, rather than unilateral peritonsillar/palatal swelling with uvular deviation.', 4),
('c6000000-0000-0000-0000-000000000004', 'E', $x$Ludwig's angina$x$, false, $x$Ruled out because Ludwig's angina is a bilateral cellulitis of the submandibular/sublingual floor of mouth causing tongue elevation and airway compromise, typically arising from a dental infection, not unilateral peritonsillar swelling.$x$, 5),
('c6000000-0000-0000-0000-000000000005', 'A', 'Repeat attempts at bag-mask ventilation with a different sized mask', false, 'Ruled out because repeated attempts at a technique that has already failed delay definitive airway rescue in a rapidly desaturating patient; escalation to front-of-neck access is required.', 1),
('c6000000-0000-0000-0000-000000000005', 'B', 'Administer high-dose intravenous corticosteroids and wait for effect', false, 'Ruled out because steroids take time to act and will not address an immediately life-threatening failed airway; the patient needs an emergency surgical airway now.', 2),
('c6000000-0000-0000-0000-000000000005', 'C', 'Emergency front-of-neck access (cricothyroidotomy)', true, $x$Correct. This is a 'can't intubate, can't ventilate' scenario with failed basic airway manoeuvres and failed supraglottic device; the recognised next step in a deteriorating hypoxic patient is emergency front-of-neck access (surgical or needle cricothyroidotomy) to secure an airway below the level of obstruction.$x$, 3),
('c6000000-0000-0000-0000-000000000005', 'D', 'Perform a further attempt at direct laryngoscopy and intubation with a different blade', false, $x$Ruled out because in a declared can't-intubate-can't-ventilate emergency with ongoing desaturation, further intubation attempts should not delay emergency front-of-neck access.$x$, 4),
('c6000000-0000-0000-0000-000000000005', 'E', 'Give intramuscular adrenaline and observe for improvement', false, 'Ruled out because there is no indication this is anaphylaxis; the priority in a failed airway with critical hypoxia is immediate surgical airway access, not empirical adrenaline.', 5),
('c6000000-0000-0000-0000-000000000006', 'A', 'Simple otitis externa', false, 'Ruled out because simple otitis externa does not cause cranial nerve palsies or granulation tissue with disproportionate pain; these findings indicate extension of infection into bone and surrounding structures.', 1),
('c6000000-0000-0000-0000-000000000006', 'B', 'Acute otitis media with mastoiditis', false, 'Ruled out because the clinical picture centres on the external canal (granulation tissue, canal discharge) in a diabetic patient rather than middle ear/mastoid signs, and malignant otitis externa is the key diagnosis to exclude given the risk factors and facial palsy.', 2),
('c6000000-0000-0000-0000-000000000006', 'C', 'Malignant (necrotising) otitis externa', true, 'Correct. Severe, persistent otitis externa with granulation tissue in the canal, disproportionate pain, and new facial nerve palsy in a patient with poorly controlled diabetes is characteristic of malignant otitis externa, a skull base osteomyelitis usually caused by Pseudomonas aeruginosa, requiring urgent ENT referral and prolonged antipseudomonal antibiotics.', 3),
('c6000000-0000-0000-0000-000000000006', 'D', $x$Bell's palsy$x$, false, $x$Ruled out because Bell's palsy is an idiopathic facial nerve palsy without associated severe ear pain, discharge, or granulation tissue; the presence of a chronic ear infection with diabetes makes malignant otitis externa far more likely and must be excluded.$x$, 4),
('c6000000-0000-0000-0000-000000000006', 'E', 'Cholesteatoma', false, 'Ruled out because cholesteatoma typically presents with chronic foul-smelling discharge and conductive hearing loss with a retraction pocket or attic defect on otoscopy, not primarily granulation tissue with severe pain and facial palsy in an uncontrolled diabetic.', 5),
('c6000000-0000-0000-0000-000000000007', 'A', 'Urgent ENT referral for incision and drainage of the septal haematoma', true, 'Correct. A bluish, fluctuant bilateral septal swelling after nasal trauma is a septal haematoma, which requires urgent incision and drainage to prevent septal cartilage necrosis (from pressure on its blood supply) and permanent saddle-nose deformity, as well as risk of abscess formation.', 1),
('c6000000-0000-0000-0000-000000000007', 'B', 'Reassure and advise ice packs with review in the fracture clinic in 2 weeks', false, 'Ruled out because an untreated septal haematoma can cause irreversible cartilage necrosis within days; this requires same-day drainage, not delayed outpatient review.', 2),
('c6000000-0000-0000-0000-000000000007', 'C', 'Arrange plain X-rays of the nasal bones before any intervention', false, 'Ruled out because nasal bone X-rays have poor sensitivity/specificity and do not change the urgent need to drain a septal haematoma, which is a clinical diagnosis on examination.', 3),
('c6000000-0000-0000-0000-000000000007', 'D', 'Prescribe oral antibiotics only and discharge', false, 'Ruled out because antibiotics alone do not relieve the pressure effect causing cartilage ischaemia; the haematoma must be drained, with antibiotics as an adjunct if needed.', 4),
('c6000000-0000-0000-0000-000000000007', 'E', 'Apply bilateral nasal packing without drainage and discharge', false, $x$Ruled out because packing alone does not evacuate the haematoma; incision and drainage is required to relieve pressure on the septal cartilage's blood supply.$x$, 5),
('c6000000-0000-0000-0000-000000000008', 'A', 'Immediate intubation in the emergency department', false, 'Ruled out because this child has moderate, not severe or life-threatening, croup (alert, maintaining saturations, no severe distress or altered consciousness); intubation is reserved for impending respiratory failure.', 1),
('c6000000-0000-0000-0000-000000000008', 'B', 'Oral dexamethasone', true, 'Correct. This is moderate croup (laryngotracheobronchitis) - barking cough, hoarse voice, stridor at rest with mild recession, but alert and maintaining oxygenation. A single dose of oral dexamethasone is first-line to reduce airway oedema and severity/duration of symptoms.', 2),
('c6000000-0000-0000-0000-000000000008', 'C', 'Reassure and discharge with no treatment as croup is self-limiting', false, 'Ruled out because moderate croup with stridor at rest warrants treatment with corticosteroids to reduce severity and complication risk, not discharge without any intervention.', 3),
('c6000000-0000-0000-0000-000000000008', 'D', 'Broad-spectrum intravenous antibiotics', false, 'Ruled out because croup is almost always viral (commonly parainfluenza virus); antibiotics have no role unless a bacterial complication is suspected.', 4),
('c6000000-0000-0000-0000-000000000008', 'E', 'Nebulised salbutamol', false, 'Ruled out because salbutamol is a bronchodilator for lower airway (bronchospasm) disease and does not address the laryngeal/subglottic oedema causing stridor in croup; nebulised adrenaline is used in severe croup, not salbutamol.', 5),
('c6000000-0000-0000-0000-000000000009', 'A', 'Arrange outpatient maxillofacial follow-up in one week', false, 'Ruled out because this is an airway emergency with impending obstruction; it needs immediate hospital management, not deferred outpatient review.', 1),
('c6000000-0000-0000-0000-000000000009', 'B', 'Give oral antibiotics and discharge with safety-netting', false, $x$Ruled out because Ludwig's angina with developing stridor is a life-threatening emergency requiring admission, IV antibiotics, and urgent airway management, not oral antibiotics and discharge.$x$, 2),
('c6000000-0000-0000-0000-000000000009', 'C', 'Perform incision and drainage at the bedside without airway support', false, $x$Ruled out because Ludwig's angina classically produces a diffuse, non-fluctuant, board-like cellulitis rather than a discrete abscess, and any intervention should occur with anaesthetic support given the high risk of airway compromise, not as an unsupported bedside procedure.$x$, 3),
('c6000000-0000-0000-0000-000000000009', 'D', 'Start nebulised salbutamol for the stridor', false, 'Ruled out because the stridor here is from upper airway soft tissue swelling/obstruction, not bronchospasm; salbutamol will not relieve mechanical obstruction and definitive airway assessment must not be delayed.', 4),
('c6000000-0000-0000-0000-000000000009', 'E', 'Urgent senior anaesthetic and ENT/maxillofacial review for airway assessment and securing the airway', true, $x$Correct. This is Ludwig's angina - a rapidly progressive bilateral cellulitis of the submandibular/sublingual spaces causing tongue elevation, trismus, and airway compromise, typically arising from dental infection. Developing stridor signals impending airway obstruction, so the immediate priority is urgent senior airway assessment (anaesthetics, ENT, maxillofacial surgery) alongside IV antibiotics, as the airway can obstruct rapidly and may need early, controlled intervention (e.g. awake fibre-optic intubation or tracheostomy).$x$, 5),
('c6000000-0000-0000-0000-000000000010', 'A', 'Posterior circulation stroke', false, 'Ruled out because the HINTS findings here (abnormal head impulse test, unidirectional fixation-suppressed nystagmus, no skew deviation, intact other neurology) point towards a peripheral cause; a central (stroke) cause would more typically show a normal head impulse test with direction-changing nystagmus and other focal signs.', 1),
('c6000000-0000-0000-0000-000000000010', 'B', 'Benign paroxysmal positional vertigo (BPPV)', false, 'Ruled out because BPPV causes brief, positional episodes of vertigo triggered by head movement (seconds, provoked by the Dix-Hallpike test), not continuous vertigo lasting hours.', 2),
('c6000000-0000-0000-0000-000000000010', 'C', $x$Meniere's disease$x$, false, $x$Ruled out because Meniere's disease classically presents with episodic vertigo accompanied by fluctuating hearing loss, tinnitus, and aural fullness, which are absent here.$x$, 3),
('c6000000-0000-0000-0000-000000000010', 'D', 'Vestibular neuritis', true, 'Correct. Acute, continuous (not positional/episodic) vertigo with an abnormal head impulse test, unidirectional horizontal nystagmus that suppresses with fixation, and no hearing loss or focal neurology is typical of vestibular neuritis (peripheral cause), distinguishing it from a central cause such as stroke.', 4),
('c6000000-0000-0000-0000-000000000010', 'E', 'Acoustic neuroma (vestibular schwannoma)', false, 'Ruled out because acoustic neuroma typically causes gradual, progressive unilateral hearing loss and tinnitus with more insidious vestibular symptoms, not an acute single episode of severe continuous vertigo.', 5),
('c6000000-0000-0000-0000-000000000011', 'A', 'Simple viral pharyngitis', false, 'Ruled out because simple pharyngitis does not cause torticollis, drooling, or prevertebral soft tissue widening on imaging; these findings indicate a deep neck space collection.', 1),
('c6000000-0000-0000-0000-000000000011', 'B', 'Meningitis', false, 'Ruled out because while neck stiffness raises concern for meningitis, the pattern of painful restricted movement in all directions (rather than isolated resistance to flexion with photophobia/rash) combined with drooling and prevertebral widening on X-ray points to a local retropharyngeal collection rather than meningeal irritation, though both should be considered and meningitis actively excluded if doubt remains.', 2),
('c6000000-0000-0000-0000-000000000011', 'C', 'Retropharyngeal abscess', true, 'Correct. Fever, neck stiffness/torticollis, painful restricted neck movement, and drooling following a recent URTI in a young child, with widened prevertebral soft tissue space on lateral neck X-ray, is characteristic of a retropharyngeal abscess, which requires urgent ENT referral, cross-sectional imaging (CT neck), and IV antibiotics +/- surgical drainage.', 3),
('c6000000-0000-0000-0000-000000000011', 'D', 'Discitis', false, 'Ruled out because discitis typically causes back pain and refusal to walk/sit rather than this pattern of neck stiffness, drooling, and prevertebral soft tissue widening on a lateral neck film.', 4),
('c6000000-0000-0000-0000-000000000011', 'E', 'Mumps parotitis', false, 'Ruled out because mumps causes parotid gland swelling anterior to the ear, not neck stiffness, drooling, or prevertebral widening on imaging.', 5),
('c6000000-0000-0000-0000-000000000012', 'A', 'The anterior pack has simply not been left in long enough and should be left for 10 more minutes with no other action', false, 'Ruled out because ongoing visible bleeding into the throat despite a correctly placed anterior pack indicates the bleeding source is posterior to the pack, so waiting longer without escalation will not resolve it.', 1),
('c6000000-0000-0000-0000-000000000012', 'B', 'This is normal and the patient can be discharged with the pack in place', false, 'Ruled out because continued active bleeding into the oropharynx despite packing is not an expected benign finding and needs further intervention/referral, not discharge.', 2),
('c6000000-0000-0000-0000-000000000012', 'C', 'Remove the anterior pack immediately as it has failed and is not needed', false, 'Ruled out because the anterior pack should not simply be removed and abandoned; the patient needs escalation to posterior packing/balloon tamponade or definitive treatment, and premature removal could worsen bleeding.', 3),
('c6000000-0000-0000-0000-000000000012', 'D', 'Ongoing posterior bleeding requiring urgent ENT referral for posterior packing or balloon tamponade', true, 'Correct. Continued bleeding into the oropharynx despite an adequate anterior pack suggests a posterior source of epistaxis, which anterior packing alone cannot control; this requires urgent ENT referral for posterior packing (e.g., a postnasal pack or balloon device) and possible admission, as posterior bleeds are more likely to need surgical or radiological intervention.', 4),
('c6000000-0000-0000-0000-000000000012', 'E', 'Administer intravenous tranexamic acid alone and observe without ENT involvement', false, 'Ruled out because tranexamic acid may be a useful adjunct but does not replace mechanical control of a posterior bleed; ENT referral for posterior packing or further intervention is required.', 5),
('c6000000-0000-0000-0000-000000000013', 'A', 'Prescribe a course of oral antibiotics and review in 2 weeks', false, 'Ruled out because antibiotics do not address the underlying retained foreign body, which is the cause of the discharge and needs mechanical removal.', 1),
('c6000000-0000-0000-0000-000000000013', 'B', 'Refer for prompt removal of the nasal foreign body by an appropriately experienced clinician', true, 'Correct. Unilateral foul-smelling, blood-stained nasal discharge in a young child is highly suggestive of a retained nasal foreign body, confirmed here on examination; it should be removed promptly by someone experienced in paediatric nasal foreign body removal to avoid complications such as mucosal ulceration, infection, or (with button batteries) rapid tissue necrosis.', 2),
('c6000000-0000-0000-0000-000000000013', 'C', 'Reassure the parents that this will resolve on its own and needs no intervention', false, 'Ruled out because a retained nasal foreign body will not resolve spontaneously and risks complications the longer it remains in place, particularly with certain object types (e.g. button batteries).', 3),
('c6000000-0000-0000-0000-000000000013', 'D', 'Irrigate the nose vigorously with saline at home as first-line treatment', false, 'Ruled out because vigorous nasal irrigation risks pushing the foreign body further into the nasal cavity or into the airway, and objects such as button batteries require urgent same-day removal rather than home irrigation.', 4),
('c6000000-0000-0000-0000-000000000013', 'E', 'Arrange a CT scan of the sinuses before any other action', false, 'Ruled out because the foreign body is already directly visualised on anterior rhinoscopy; imaging is unnecessary and would only delay definitive removal.', 5),
('c6000000-0000-0000-0000-000000000014', 'A', 'Analgesia and safety-netting advice, with antibiotics reserved for if symptoms do not improve within 2-3 days or worsen', true, $x$Correct. Most acute otitis media in otherwise well children is self-limiting and viral or resolves without antibiotics; NICE guidance supports a 'watchful waiting' approach with regular analgesia (paracetamol/ibuprofen) and clear safety-netting advice, reserving antibiotics for children who do not improve within 2-3 days, are systemically unwell, or are at higher risk of complications.$x$, 1),
('c6000000-0000-0000-0000-000000000014', 'B', 'Immediate oral amoxicillin for all children with acute otitis media', false, 'Ruled out because routine immediate antibiotics for uncomplicated acute otitis media in an otherwise well child do not significantly change outcomes and are not first-line; a delayed/watchful waiting approach is preferred unless red flags are present.', 2),
('c6000000-0000-0000-0000-000000000014', 'C', 'Urgent ENT referral for grommet insertion', false, 'Ruled out because a single episode of acute otitis media does not warrant grommet insertion, which is reserved for recurrent or persistent otitis media with effusion causing hearing/developmental concerns.', 3),
('c6000000-0000-0000-0000-000000000014', 'D', 'Topical antibiotic-steroid ear drops', false, 'Ruled out because topical ear drops are used for otitis externa (outer ear canal infection) with an intact eardrum accessible to topical treatment, not for acute otitis media, which is a middle ear infection behind an intact tympanic membrane.', 4),
('c6000000-0000-0000-0000-000000000014', 'E', 'Admission for intravenous antibiotics', false, 'Ruled out because this child is systemically well with no red flags (e.g. no signs of mastoiditis, meningism, or severe illness); admission for IV antibiotics is unnecessary for uncomplicated acute otitis media.', 5),
('c6000000-0000-0000-0000-000000000015', 'A', 'Tympanometry alone', false, 'Ruled out because tympanometry assesses middle ear function/compliance and is used for conditions like otitis media with effusion, not for identifying a retrocochlear lesion causing asymmetric sensorineural hearing loss.', 1),
('c6000000-0000-0000-0000-000000000015', 'B', 'CT scan of the temporal bones without contrast', false, 'Ruled out because CT is less sensitive than MRI for detecting small cerebellopontine angle tumours such as vestibular schwannomas; MRI with contrast is the gold-standard investigation.', 2),
('c6000000-0000-0000-0000-000000000015', 'C', 'Reassurance with no further investigation, as this is likely presbycusis', false, 'Ruled out because presbycusis is typically bilateral and symmetric, not unilateral and asymmetric with additional cranial nerve symptoms (facial numbness); asymmetric sensorineural hearing loss requires further investigation to exclude a retrocochlear cause.', 3),
('c6000000-0000-0000-0000-000000000015', 'D', 'Pure tone audiometry repeated in 12 months with no other action', false, $x$Ruled out because unexplained asymmetric sensorineural hearing loss with associated neurological symptoms warrants prompt imaging now, not simply repeating the same test after a year's delay.$x$, 4),
('c6000000-0000-0000-0000-000000000015', 'E', 'MRI of the internal auditory meatus with contrast', true, 'Correct. Unilateral, progressive, asymmetric sensorineural hearing loss with tinnitus, imbalance, and facial numbness (suggesting trigeminal nerve involvement) raises strong suspicion of a vestibular schwannoma (acoustic neuroma) in the cerebellopontine angle; MRI of the internal auditory meatus with contrast is the investigation of choice to confirm this.', 5),
('c6000000-0000-0000-0000-000000000016', 'A', 'Acute otitis media', false, 'Ruled out because acute otitis media is a middle ear infection behind the tympanic membrane, typically without tragal tenderness or external canal swelling, and usually follows an upper respiratory infection rather than swimming.', 1),
('c6000000-0000-0000-0000-000000000016', 'B', 'Malignant otitis externa', false, 'Ruled out because there is no mention of risk factors such as diabetes/immunosuppression, disproportionate pain, granulation tissue, or cranial nerve involvement, which would suggest the more severe, invasive malignant otitis externa.', 2),
('c6000000-0000-0000-0000-000000000016', 'C', 'Cholesteatoma', false, 'Ruled out because cholesteatoma typically presents with chronic, painless, foul-smelling discharge and progressive conductive hearing loss, not acute painful canal swelling with tragal tenderness after swimming.', 3),
('c6000000-0000-0000-0000-000000000016', 'D', 'Herpes zoster oticus (Ramsay Hunt syndrome)', false, 'Ruled out because Ramsay Hunt syndrome typically presents with a vesicular rash in the ear canal/pinna, severe otalgia, and facial nerve palsy, none of which are described here.', 4),
('c6000000-0000-0000-0000-000000000016', 'E', 'Otitis externa', true, 'Correct. Ear canal pain worsened by movement of the pinna/tragus, canal erythema and swelling, discharge, and a recent swimming history are characteristic of otitis externa (inflammation/infection of the external auditory canal), commonly caused by Pseudomonas aeruginosa or Staphylococcus aureus.', 5),
('c6000000-0000-0000-0000-000000000017', 'A', 'Acute otitis media', false, 'Ruled out because acute otitis media presents acutely with pain and fever, not a decade-long history of chronic painless discharge and a retraction pocket with keratin debris.', 1),
('c6000000-0000-0000-0000-000000000017', 'B', 'Otitis externa', false, 'Ruled out because otitis externa affects the external ear canal with tragal tenderness, not a retraction pocket with keratin debris in the tympanic membrane itself.', 2),
('c6000000-0000-0000-0000-000000000017', 'C', 'Cholesteatoma', true, 'Correct. Chronic, painless, foul-smelling otorrhoea with progressive conductive hearing loss and a postero-superior retraction pocket containing keratin debris is classic for cholesteatoma, an abnormal accumulation of squamous epithelium in the middle ear/mastoid that can erode surrounding bone and requires ENT referral for surgical management.', 3),
('c6000000-0000-0000-0000-000000000017', 'D', 'Otosclerosis', false, 'Ruled out because otosclerosis causes progressive conductive hearing loss due to stapes fixation with a normal-appearing (not perforated or debris-filled) tympanic membrane, without chronic discharge.', 4),
('c6000000-0000-0000-0000-000000000017', 'E', 'Presbycusis', false, 'Ruled out because presbycusis is a bilateral, symmetric, age-related sensorineural hearing loss without discharge, perforation, or retraction pocket findings.', 5),
('c6000000-0000-0000-0000-000000000018', 'A', 'Otosclerosis', false, 'Ruled out because otosclerosis typically causes progressive conductive (not sensorineural) hearing loss, often presenting at a younger age and sometimes with a family history.', 1),
('c6000000-0000-0000-0000-000000000018', 'B', 'Presbycusis (age-related sensorineural hearing loss)', true, 'Correct. Gradual, bilateral, symmetric high-frequency sensorineural hearing loss with difficulty hearing in noisy environments in an older adult, with a normal otoscopic examination, is the classic presentation of presbycusis, the most common cause of hearing loss in the elderly.', 2),
('c6000000-0000-0000-0000-000000000018', 'C', $x$Meniere's disease$x$, false, $x$Ruled out because Meniere's disease presents with episodic vertigo, fluctuating hearing loss, tinnitus, and aural fullness, not a steady gradual bilateral decline without vertigo.$x$, 3),
('c6000000-0000-0000-0000-000000000018', 'D', 'Noise-induced hearing loss', false, 'Ruled out because there is no history of significant noise exposure given, and while it can also cause high-frequency sensorineural loss, the gradual bilateral decline purely with advancing age here is most consistent with presbycusis.', 4),
('c6000000-0000-0000-0000-000000000018', 'E', 'Otitis media with effusion', false, 'Ruled out because otitis media with effusion causes conductive hearing loss with an abnormal (dull, retracted) tympanic membrane, not sensorineural loss with a normal otoscopic examination.', 5),
('c6000000-0000-0000-0000-000000000019', 'A', 'Benign paroxysmal positional vertigo (BPPV)', false, 'Ruled out because BPPV causes brief (seconds) positional vertigo triggered by head movement, without associated hearing loss, tinnitus, or aural fullness.', 1),
('c6000000-0000-0000-0000-000000000019', 'B', 'Vestibular neuritis', false, 'Ruled out because vestibular neuritis causes a single acute episode of continuous vertigo lasting days, without hearing loss, rather than recurrent episodes with fluctuating hearing changes.', 2),
('c6000000-0000-0000-0000-000000000019', 'C', 'Acoustic neuroma', false, 'Ruled out because acoustic neuroma typically causes a slowly progressive, non-fluctuating unilateral hearing loss and imbalance rather than discrete recurrent vertigo episodes with fluctuating hearing.', 3),
('c6000000-0000-0000-0000-000000000019', 'D', $x$Meniere's disease$x$, true, $x$Correct. Recurrent episodic vertigo lasting minutes to hours, with fluctuating low-frequency sensorineural hearing loss, tinnitus, and aural fullness, is the classic triad/tetrad of Meniere's disease, thought to be caused by endolymphatic hydrops.$x$, 4),
('c6000000-0000-0000-0000-000000000019', 'E', 'Migrainous vertigo (vestibular migraine)', false, 'Ruled out because vestibular migraine is typically associated with headache and photophobia/phonophobia rather than progressive fluctuating low-frequency sensorineural hearing loss and aural fullness.', 5),
('c6000000-0000-0000-0000-000000000020', 'A', 'Epley manoeuvre', true, 'Correct. Brief, positional vertigo triggered by specific head movements, with a positive Dix-Hallpike test showing fatigable rotatory nystagmus, and no hearing loss or tinnitus, is characteristic of benign paroxysmal positional vertigo (BPPV) due to canalithiasis of the posterior semicircular canal; the Epley (canalith repositioning) manoeuvre is first-line treatment.', 1),
('c6000000-0000-0000-0000-000000000020', 'B', 'Oral betahistine as first-line treatment', false, 'Ruled out because betahistine has limited evidence in BPPV; the Epley manoeuvre, a mechanical repositioning technique, is the recommended first-line treatment.', 2),
('c6000000-0000-0000-0000-000000000020', 'C', 'Urgent MRI brain to exclude posterior circulation stroke', false, 'Ruled out because the classic history and examination findings (brief positional episodes, fatigable nystagmus on Dix-Hallpike, no other neurology) are diagnostic of BPPV; urgent imaging is reserved for atypical presentations or when central causes are suspected.', 3),
('c6000000-0000-0000-0000-000000000020', 'D', 'Vestibular sedatives such as prochlorperazine for long-term use', false, 'Ruled out because vestibular sedatives may help acute nausea but do not treat the underlying cause and are not appropriate for long-term use in BPPV; the Epley manoeuvre addresses the mechanical cause directly.', 4),
('c6000000-0000-0000-0000-000000000020', 'E', 'Bed rest and avoidance of head movement for 2 weeks', false, 'Ruled out because prolonged avoidance of movement does not resolve BPPV and delays recovery; the Epley manoeuvre is a quick, effective, definitive treatment.', 5),
('c6000000-0000-0000-0000-000000000021', 'A', 'Otosclerosis', true, 'Correct. Progressive conductive hearing loss beginning in young adulthood, often exacerbated by pregnancy, a positive family history, paracusis willisii (hearing better in noisy environments), a normal tympanic membrane, and a Carhart notch on audiometry are all classic features of otosclerosis, caused by abnormal bone remodelling fixing the stapes footplate.', 1),
('c6000000-0000-0000-0000-000000000021', 'B', 'Presbycusis', false, 'Ruled out because presbycusis is an age-related sensorineural hearing loss occurring later in life, not a conductive loss with family history and pregnancy-related onset in a young woman.', 2),
('c6000000-0000-0000-0000-000000000021', 'C', 'Cholesteatoma', false, 'Ruled out because cholesteatoma is associated with chronic discharge and an abnormal tympanic membrane with a retraction pocket, not a normal otoscopic examination.', 3),
('c6000000-0000-0000-0000-000000000021', 'D', $x$Meniere's disease$x$, false, $x$Ruled out because Meniere's disease causes episodic vertigo with fluctuating sensorineural hearing loss and tinnitus, not a steadily progressive conductive hearing loss with a normal ear examination.$x$, 4),
('c6000000-0000-0000-0000-000000000021', 'E', 'Noise-induced hearing loss', false, 'Ruled out because noise-induced hearing loss is sensorineural (typically a 4000 Hz notch) and related to noise exposure, not conductive with a Carhart notch and strong family history.', 5),
('c6000000-0000-0000-0000-000000000022', 'A', 'Reassure that this will resolve spontaneously and review in 3 months', false, 'Ruled out because sudden sensorineural hearing loss is time-critical; delaying treatment reduces the chance of hearing recovery, so urgent same-day ENT referral is required, not a 3-month wait.', 1),
('c6000000-0000-0000-0000-000000000022', 'B', 'Prescribe topical antibiotic ear drops', false, 'Ruled out because topical ear drops treat external canal or middle ear infections with an intact/perforated eardrum accessible topically; they have no role in sudden sensorineural (inner ear/nerve) hearing loss.', 2),
('c6000000-0000-0000-0000-000000000022', 'C', 'Syringe the ear to remove presumed wax impaction', false, 'Ruled out because otoscopy is stated as normal, excluding wax impaction as the cause; syringing would not address a sensorineural hearing loss and delays appropriate urgent referral.', 3),
('c6000000-0000-0000-0000-000000000022', 'D', 'Arrange routine outpatient audiology review in 6 weeks', false, 'Ruled out because sudden sensorineural hearing loss requires urgent, not routine, assessment, since the window for effective steroid treatment is time-limited.', 4),
('c6000000-0000-0000-0000-000000000022', 'E', 'Urgent (same-day/within 24 hours) ENT referral for consideration of oral corticosteroids', true, 'Correct. Sudden sensorineural hearing loss (idiopathic in most cases) is an otological emergency requiring urgent ENT assessment, as early treatment with oral (or intratympanic) corticosteroids within the first 1-2 weeks offers the best chance of hearing recovery; other causes (e.g. stroke, acoustic neuroma) also need to be excluded.', 5),
('c6000000-0000-0000-0000-000000000023', 'A', 'Acute otitis media', false, 'Ruled out because acute otitis media presents acutely with pain, fever, and a bulging erythematous tympanic membrane, not a painless, non-erythematous effusion with a fluid level.', 1),
('c6000000-0000-0000-0000-000000000023', 'B', 'Otitis externa', false, 'Ruled out because otitis externa is an external canal infection with tragal tenderness and canal swelling, not a middle ear effusion behind an intact eardrum.', 2),
('c6000000-0000-0000-0000-000000000023', 'C', 'Otitis media with effusion (glue ear)', true, 'Correct. A dull, retracted tympanic membrane with a visible fluid level, a flat (type B) tympanometry trace, and behavioural signs of hearing difficulty without pain or infection signs are characteristic of otitis media with effusion (glue ear), a common cause of conductive hearing loss in children.', 3),
('c6000000-0000-0000-0000-000000000023', 'D', 'Sensorineural hearing loss due to congenital cytomegalovirus infection', false, 'Ruled out because the otoscopic and tympanometric findings here (retracted membrane, fluid level, flat trace) point to a conductive cause (middle ear effusion), not a sensorineural cause.', 4),
('c6000000-0000-0000-0000-000000000023', 'E', 'Cholesteatoma', false, 'Ruled out because cholesteatoma presents with chronic foul discharge and a retraction pocket with keratin debris, not simply a fluid-filled middle ear without discharge.', 5),
('c6000000-0000-0000-0000-000000000024', 'A', $x$Bell's palsy$x$, false, $x$Ruled out because Bell's palsy is an idiopathic facial nerve palsy without a vesicular rash, severe otalgia, or hearing loss; the presence of vesicles in the ear canal here points specifically to Ramsay Hunt syndrome.$x$, 1),
('c6000000-0000-0000-0000-000000000024', 'B', 'Stroke (cerebrovascular accident)', false, $x$Ruled out because a facial nerve palsy affecting both the forehead and lower face is a lower motor neurone pattern (as seen in Bell's palsy/Ramsay Hunt), whereas stroke typically causes an upper motor neurone pattern sparing the forehead; the vesicular rash and ear pain also point away from stroke.$x$, 2),
('c6000000-0000-0000-0000-000000000024', 'C', 'Otitis externa', false, 'Ruled out because otitis externa does not cause facial nerve palsy or a vesicular rash; these features indicate viral reactivation affecting the facial nerve (Ramsay Hunt syndrome).', 3),
('c6000000-0000-0000-0000-000000000024', 'D', 'Ramsay Hunt syndrome (herpes zoster oticus)', true, 'Correct. Facial nerve palsy accompanied by severe otalgia, a vesicular rash on the pinna/external ear canal, and hearing loss/tinnitus is characteristic of Ramsay Hunt syndrome, caused by reactivation of varicella zoster virus affecting the facial and vestibulocochlear nerves; treatment requires prompt oral antiviral therapy plus corticosteroids.', 4),
('c6000000-0000-0000-0000-000000000024', 'E', 'Acute otitis media', false, 'Ruled out because acute otitis media does not typically cause facial nerve palsy or a vesicular rash on the pinna/ear canal; these findings are specific to herpes zoster reactivation.', 5),
('c6000000-0000-0000-0000-000000000025', 'A', 'Irrigate the ear canal vigorously with water immediately regardless of object type', false, $x$Ruled out because irrigation is contraindicated for certain foreign bodies (e.g. those that swell with water, or button batteries) and technique should be tailored to the object and clinical context; for a smooth bead, syringing may be appropriate but 'vigorous irrigation regardless of type' is not correct in general.$x$, 1),
('c6000000-0000-0000-0000-000000000025', 'B', 'Attempt removal by an experienced clinician using appropriate technique (e.g. microsuction, fine forceps, or syringing if suitable), referring to ENT if unsuccessful', true, 'Correct. A visible, non-organic foreign body away from the tympanic membrane in a cooperative or restrainable child can be attempted for removal by an appropriately experienced clinician using suitable technique; if removal is unsuccessful or the child is uncooperative, prompt ENT referral is appropriate rather than repeated risky attempts.', 2),
('c6000000-0000-0000-0000-000000000025', 'C', 'Reassure and advise the foreign body will pass on its own with no removal needed', false, 'Ruled out because a retained ear canal foreign body will not simply pass on its own and needs active removal to prevent complications such as canal trauma, infection, or pressure injury.', 3),
('c6000000-0000-0000-0000-000000000025', 'D', 'Refer for removal under general anaesthetic as first-line for all ear foreign bodies', false, 'Ruled out because general anaesthesia is reserved for foreign bodies that cannot be removed at the bedside/outpatient setting (e.g. uncooperative child, object touching or embedded near the tympanic membrane), not as the first-line approach for every case.', 4),
('c6000000-0000-0000-0000-000000000025', 'E', 'Apply topical antibiotic ear drops and review in one week', false, 'Ruled out because ear drops do not remove a foreign body; the object itself must be extracted, with drops only relevant if secondary infection develops afterward.', 5),
('c6000000-0000-0000-0000-000000000026', 'A', 'Analgesia, nasal saline irrigation, and safety-netting advice, reserving antibiotics for symptoms persisting beyond 10 days or if worsening', true, 'Correct. Acute rhinosinusitis is usually viral and self-limiting; most guidelines recommend symptomatic treatment (analgesia, nasal saline, consider intranasal corticosteroids if symptoms are prolonged) with antibiotics reserved for symptoms lasting more than 10 days without improvement, marked systemic upset, or high risk of complications.', 1),
('c6000000-0000-0000-0000-000000000026', 'B', 'Immediate oral antibiotics for all patients with acute sinusitis symptoms', false, 'Ruled out because most acute rhinosinusitis is viral, and immediate antibiotics do not significantly improve outcomes in uncomplicated cases; they are reserved for prolonged or severe symptoms.', 2),
('c6000000-0000-0000-0000-000000000026', 'C', 'Urgent CT scan of the sinuses before any treatment', false, 'Ruled out because imaging is not required for typical uncomplicated acute rhinosinusitis; it is reserved for suspected complications, red flags, or diagnostic uncertainty.', 3),
('c6000000-0000-0000-0000-000000000026', 'D', 'Urgent ENT referral for functional endoscopic sinus surgery', false, 'Ruled out because surgery is reserved for chronic rhinosinusitis unresponsive to medical treatment or complications, not first-line management of a straightforward acute presentation.', 4),
('c6000000-0000-0000-0000-000000000026', 'E', 'Admission for intravenous antibiotics', false, 'Ruled out because this patient has no red flags (no severe systemic illness, visual disturbance, or signs of orbital/intracranial complication) that would warrant admission for IV therapy.', 5),
('c6000000-0000-0000-0000-000000000027', 'A', 'Discharge home with oral antibiotics and review in one week', false, 'Ruled out because restricted eye movements, proptosis, and reduced visual acuity indicate orbital cellulitis, a sight-threatening emergency requiring admission and IV antibiotics, not outpatient oral treatment.', 1),
('c6000000-0000-0000-0000-000000000027', 'B', 'Urgent hospital admission for IV antibiotics and urgent ophthalmology/ENT assessment with contrast CT imaging', true, 'Correct. Painful, restricted eye movements, proptosis, and reduced visual acuity following sinusitis indicate orbital (not just preseptal) cellulitis, a sight- and life-threatening emergency caused by spread of sinus infection into the orbit; this requires urgent admission, IV antibiotics, contrast CT to assess for abscess, and joint ophthalmology/ENT input, with surgical drainage if an abscess is present or vision deteriorates.', 2),
('c6000000-0000-0000-0000-000000000027', 'C', 'Reassure that this is simple preseptal (periorbital) cellulitis needing only oral antibiotics', false, 'Ruled out because preseptal cellulitis does not cause painful or restricted eye movements, proptosis, or reduced visual acuity; these findings indicate the infection has spread posterior to the orbital septum (orbital cellulitis), which is more severe.', 3),
('c6000000-0000-0000-0000-000000000027', 'D', 'Arrange outpatient ophthalmology review within 2 weeks', false, 'Ruled out because the combination of proptosis, painful eye movements, and reduced vision represents an emergency requiring same-day admission and urgent assessment, not a routine outpatient appointment.', 4),
('c6000000-0000-0000-0000-000000000027', 'E', 'Perform lumbar puncture as the first investigation', false, 'Ruled out because although intracranial complications can occur with orbital cellulitis, the immediate priority is urgent imaging (CT) and treatment of the orbital infection; lumbar puncture is not the first step and may be contraindicated if raised intracranial pressure is a concern.', 5),
('c6000000-0000-0000-0000-000000000028', 'A', 'Chronic rhinosinusitis with nasal polyps', false, $x$Ruled out because chronic rhinosinusitis typically presents with facial pain/pressure, reduced sense of smell, and purulent discharge, and polyps are seen on examination; this patient's presentation with itchy eyes and seasonal pattern is more consistent with allergic rhinitis.$x$, 1),
('c6000000-0000-0000-0000-000000000028', 'B', 'Acute viral rhinitis (common cold)', false, 'Ruled out because a common cold is a short, self-limiting illness lasting days, not a 2-year history of recurrent seasonal symptoms.', 2),
('c6000000-0000-0000-0000-000000000028', 'C', 'Non-allergic (vasomotor) rhinitis', false, 'Ruled out because vasomotor rhinitis is typically perennial and triggered by non-allergic stimuli (temperature change, strong smells) rather than a clear seasonal pattern with itchy eyes and atopic history, which favour an allergic cause.', 3),
('c6000000-0000-0000-0000-000000000028', 'D', 'Nasal foreign body', false, 'Ruled out because a nasal foreign body causes unilateral symptoms, typically in young children, not bilateral seasonal symptoms in a 24-year-old with an atopic background.', 4),
('c6000000-0000-0000-0000-000000000028', 'E', 'Allergic rhinitis', true, 'Correct. Seasonal nasal congestion, clear rhinorrhoea, sneezing, and itchy watery eyes, with pale/swollen nasal mucosa and a personal history of atopy (eczema), are characteristic of allergic rhinitis, commonly triggered by seasonal allergens such as pollen (hay fever).', 5),
('c6000000-0000-0000-0000-000000000029', 'A', 'Unilateral nasal foreign body', false, 'Ruled out because foreign bodies typically occur in young children and cause unilateral foul discharge, not bilateral pale grape-like masses in a 50-year-old with asthma and aspirin sensitivity.', 1),
('c6000000-0000-0000-0000-000000000029', 'B', 'Sinonasal malignancy', false, 'Ruled out because although unilateral nasal masses can raise concern for malignancy and should always be considered/biopsied if atypical, the bilateral, pale, mobile, grape-like appearance with the classic asthma/aspirin sensitivity association is much more typical of benign nasal polyps; persistent unilateral or atypical/bleeding masses should still prompt further evaluation to exclude malignancy.', 2),
('c6000000-0000-0000-0000-000000000029', 'C', 'Allergic rhinitis alone', false, 'Ruled out because allergic rhinitis causes pale, swollen mucosa but not discrete visible grape-like polypoid masses; the described findings indicate true nasal polyps.', 3),
('c6000000-0000-0000-0000-000000000029', 'D', 'Nasal polyps (chronic rhinosinusitis with nasal polyposis)', true, $x$Correct. Bilateral pale, grape-like, mobile masses on rhinoscopy causing nasal obstruction and anosmia, in a patient with the classic association of asthma and aspirin sensitivity (Samter's triad), are characteristic of nasal polyps arising in chronic rhinosinusitis.$x$, 4),
('c6000000-0000-0000-0000-000000000029', 'E', 'Antrochoanal polyp', false, 'Ruled out because an antrochoanal polyp is typically a solitary, unilateral polyp arising from the maxillary sinus in a younger patient, rather than the bilateral polyposis seen here with the classic asthma/aspirin triad.', 5),
('c6000000-0000-0000-0000-000000000030', 'A', 'Reassure that this is likely a simple nasal polyp and review in 6 months', false, 'Ruled out because the unilateral nature, bleeding, facial numbness, and weight loss are red flags inconsistent with simple benign polyps and require urgent, not delayed, specialist assessment.', 1),
('c6000000-0000-0000-0000-000000000030', 'B', 'Prescribe a 2-week course of intranasal corticosteroids and review', false, 'Ruled out because red flag features for malignancy should prompt urgent referral for biopsy, not an empirical trial of medical therapy that would delay diagnosis.', 2),
('c6000000-0000-0000-0000-000000000030', 'C', 'Urgent (2-week wait) ENT referral for further assessment and biopsy', true, 'Correct. Unilateral nasal obstruction with blood-stained discharge, facial numbness (suggesting infraorbital/trigeminal nerve involvement), weight loss, and a firm, irregular, bleeding mass are red flag features for sinonasal malignancy; this warrants urgent specialist referral for endoscopic assessment and biopsy without delay.', 3),
('c6000000-0000-0000-0000-000000000030', 'D', 'Arrange routine (non-urgent) ENT outpatient referral', false, 'Ruled out because the constellation of red flag symptoms (unilateral bleeding mass, facial numbness, weight loss) requires urgent, expedited referral rather than a routine, non-urgent pathway.', 4),
('c6000000-0000-0000-0000-000000000030', 'E', 'Treat empirically with oral antibiotics for presumed sinusitis', false, 'Ruled out because there are no features suggesting straightforward infective sinusitis, and the red flag features described require urgent investigation for malignancy rather than empirical antibiotic treatment.', 5),
('c6000000-0000-0000-0000-000000000031', 'A', 'Arrange immediate open reduction and internal fixation today', false, 'Ruled out because surgical fixation is not the first step for a simple nasal fracture; assessment for deformity is best done after swelling settles, and many nasal fractures are managed with closed manipulation if needed, not immediate ORIF.', 1),
('c6000000-0000-0000-0000-000000000031', 'B', 'Reassure with no follow-up required as nasal fractures never need treatment', false, 'Ruled out because some nasal fractures cause cosmetic or functional deformity that benefits from manipulation within the appropriate time window (typically within about 2 weeks), so follow-up assessment is needed rather than assuming no treatment will ever be required.', 2),
('c6000000-0000-0000-0000-000000000031', 'C', 'Advise analgesia and review in ENT/fracture clinic in 5-7 days once swelling has settled to assess for deformity', true, 'Correct. Simple nasal bone injury without red flags (no septal haematoma, CSF leak, or visual disturbance) is best managed with initial analgesia and safety-netting, then reviewed after swelling has subsided (typically 5-7 days) to properly assess for any residual bony deformity requiring manipulation, since immediate assessment is often obscured by swelling.', 3),
('c6000000-0000-0000-0000-000000000031', 'D', 'Perform bilateral anterior nasal packing prophylactically', false, 'Ruled out because there is no ongoing bleeding requiring packing; his epistaxis has already settled with simple pressure.', 4),
('c6000000-0000-0000-0000-000000000031', 'E', 'Arrange an urgent CT facial bones scan today before any other action', false, 'Ruled out because plain clinical assessment (deferred until swelling settles) is sufficient for an uncomplicated nasal fracture without red flags; urgent CT is not required unless there are concerning features such as suspected complex facial fractures or CSF leak.', 5),
('c6000000-0000-0000-0000-000000000032', 'A', 'Immediate ENT referral for functional endoscopic sinus surgery', false, 'Ruled out because surgery is reserved for chronic rhinosinusitis that fails an adequate trial of medical therapy (intranasal steroids, saline), not as an immediate first step.', 1),
('c6000000-0000-0000-0000-000000000032', 'B', 'A further, longer course of oral antibiotics', false, 'Ruled out because repeated antibiotics without a corticosteroid trial are not the recommended next step for chronic rhinosinusitis, which is primarily an inflammatory rather than purely infective process; antibiotics have already been tried without benefit.', 2),
('c6000000-0000-0000-0000-000000000032', 'C', 'Reassure that no further treatment is required as symptoms will resolve spontaneously', false, 'Ruled out because chronic rhinosinusitis lasting 3 months with ongoing symptoms despite prior treatment attempts is unlikely to resolve without further intervention such as intranasal steroids.', 3),
('c6000000-0000-0000-0000-000000000032', 'D', 'Arrange urgent CT sinuses before any further medical treatment', false, 'Ruled out because imaging is generally reserved for diagnostic uncertainty, red flags, or before considering surgery after failed medical therapy, not as the immediate next step ahead of a standard intranasal steroid trial.', 4),
('c6000000-0000-0000-0000-000000000032', 'E', 'Trial of a regular intranasal corticosteroid spray for at least 4-6 weeks alongside continued saline irrigation', true, 'Correct. Chronic rhinosinusitis (symptoms lasting more than 12 weeks, here 3 months) without polyps is first managed in primary care with a trial of regular intranasal corticosteroids combined with saline irrigation for an adequate period before considering further escalation or specialist referral if symptoms persist.', 5),
('c6000000-0000-0000-0000-000000000033', 'A', 'Progression of chronic rhinosinusitis unrelated to his medications', false, 'Ruled out because the clear temporal association between decongestant spray overuse and progressively worsening rebound congestion strongly points to rhinitis medicamentosa rather than coincidental progression of underlying sinus disease.', 1),
('c6000000-0000-0000-0000-000000000033', 'B', 'Rhinitis medicamentosa due to overuse of topical decongestant spray', true, 'Correct. Prolonged use (typically beyond 5-7 days) of topical sympathomimetic decongestant sprays such as oxymetazoline can cause rebound nasal congestion (rhinitis medicamentosa) due to tachyphylaxis and rebound vasodilation, with symptoms worsening the more the spray is used; management is to stop the decongestant spray, potentially with a short course of oral or intranasal corticosteroids to help withdrawal.', 2),
('c6000000-0000-0000-0000-000000000033', 'C', 'Allergic reaction to the intranasal corticosteroid spray', false, 'Ruled out because intranasal corticosteroids are not typically associated with rebound congestion in this manner; the pattern described (brief relief then rebound worsening) is specific to topical decongestant overuse.', 3),
('c6000000-0000-0000-0000-000000000033', 'D', 'Development of nasal polyps', false, 'Ruled out because there is no mention of examination findings consistent with polyps, and the clear pattern of rebound congestion with decongestant overuse is a more likely explanation for this specific symptom pattern.', 4),
('c6000000-0000-0000-0000-000000000033', 'E', 'Onset of a new upper respiratory tract viral infection', false, 'Ruled out because the symptom pattern (brief relief from spray followed by worsening rebound congestion over months of use) is a specific pharmacological effect, not the acute, self-limiting course typical of a viral URTI.', 5),
('c6000000-0000-0000-0000-000000000034', 'A', 'Bilateral allergic rhinitis', false, 'Ruled out because allergic rhinitis causes bilateral, clear, itchy symptoms, not unilateral foul purulent discharge following a history of nasal insertion.', 1),
('c6000000-0000-0000-0000-000000000034', 'B', 'Simple viral upper respiratory tract infection', false, 'Ruled out because a viral URTI typically causes bilateral clear/mucoid discharge, not unilateral foul-smelling purulent discharge with a preceding history of foreign body insertion.', 2),
('c6000000-0000-0000-0000-000000000034', 'C', 'Acute bacterial sinusitis unrelated to any foreign body', false, 'Ruled out because although secondary infection is present, the unilateral nature and the history of the child putting something up her nose strongly point to a retained foreign body as the underlying cause requiring removal, rather than isolated sinusitis.', 3),
('c6000000-0000-0000-0000-000000000034', 'D', 'Retained nasal foreign body', true, 'Correct. Unilateral, foul-smelling purulent discharge in a child following a history suggestive of something being inserted into the nose is highly suggestive of a retained nasal foreign body causing secondary infection, and the nose should be examined (with removal of the foreign body) rather than treated as simple sinusitis.', 4),
('c6000000-0000-0000-0000-000000000034', 'E', 'Nasal polyp', false, 'Ruled out because nasal polyps are usually bilateral, painless, and not associated with foul purulent discharge in the way described, and the history here specifically suggests a foreign body.', 5),
('c6000000-0000-0000-0000-000000000035', 'A', $x$Aspirin-exacerbated respiratory disease (Samter's triad)$x$, true, $x$Correct. The combination of asthma, chronic rhinosinusitis with nasal polyps, and acute respiratory/nasal symptom exacerbation after NSAID (aspirin or ibuprofen) ingestion is the classic presentation of aspirin-exacerbated respiratory disease (Samter's triad); patients should be advised to avoid NSAIDs/aspirin going forward and this should be documented clearly in their records.$x$, 1),
('c6000000-0000-0000-0000-000000000035', 'B', 'IgE-mediated anaphylaxis to ibuprofen', false, 'Ruled out because there is no rash, facial/laryngeal swelling, or hypotension described, and the specific triad of asthma, polyps, and NSAID-induced respiratory exacerbation is a pseudo-allergic reaction related to leukotriene pathway dysregulation rather than classic IgE-mediated anaphylaxis.', 2),
('c6000000-0000-0000-0000-000000000035', 'C', 'Simple viral exacerbation of asthma', false, 'Ruled out because the temporal relationship to NSAID ingestion within 30 minutes, combined with his known nasal polyps, strongly indicates a drug-triggered reaction rather than a coincidental viral trigger.', 3),
('c6000000-0000-0000-0000-000000000035', 'D', 'Acute bacterial sinusitis flare', false, 'Ruled out because the acute onset of wheeze and nasal symptoms specifically after NSAID ingestion, in a patient with the known triad components, points to aspirin-exacerbated respiratory disease rather than a bacterial sinus infection.', 4),
('c6000000-0000-0000-0000-000000000035', 'E', 'Vocal cord dysfunction', false, 'Ruled out because the clinical context (known nasal polyps and asthma, acute reaction temporally linked to NSAID ingestion) fits aspirin-exacerbated respiratory disease far better than vocal cord dysfunction, which is not typically triggered by NSAIDs.', 5),
('c6000000-0000-0000-0000-000000000036', 'A', 'Reassure and advise voice rest for a further 6 weeks before any referral', false, 'Ruled out because hoarseness persisting beyond 3-6 weeks with additional red flags (weight loss, dysphagia, significant smoking/alcohol history) should prompt urgent referral, not further watchful waiting.', 1),
('c6000000-0000-0000-0000-000000000036', 'B', 'Prescribe a proton pump inhibitor for presumed laryngopharyngeal reflux and review in 8 weeks', false, 'Ruled out because although reflux can cause hoarseness, the presence of multiple red flags (persistent duration, weight loss, dysphagia, heavy smoking/alcohol history) means malignancy must be excluded urgently rather than trialling empirical reflux treatment first.', 2),
('c6000000-0000-0000-0000-000000000036', 'C', 'Arrange routine (non-urgent) ENT outpatient referral', false, 'Ruled out because the red flag features described (persistent hoarseness beyond 3 weeks with weight loss and dysphagia in a high-risk patient) require an urgent, expedited pathway rather than a routine referral.', 3),
('c6000000-0000-0000-0000-000000000036', 'D', 'Start empirical antibiotics for presumed laryngitis', false, 'Ruled out because there is no evidence of an acute infective laryngitis here; the chronicity and red flag features require urgent investigation for malignancy, not empirical antibiotics.', 4),
('c6000000-0000-0000-0000-000000000036', 'E', 'Urgent (2-week wait) ENT referral for laryngoscopy', true, 'Correct. Persistent hoarseness lasting more than 3 weeks (here 6 weeks) in a patient with significant smoking and alcohol history, together with dysphagia and unintentional weight loss, are red flag features for laryngeal or head and neck malignancy; this warrants urgent 2-week wait referral for laryngoscopy and further assessment.', 5),
('c6000000-0000-0000-0000-000000000037', 'A', 'Urgent (2-week wait) ENT referral for further assessment including examination of the upper aerodigestive tract', true, 'Correct. A persistent, enlarging, firm, fixed cervical lymph node in an older patient with significant smoking and alcohol history, associated with referred otalgia and dysphagia, is highly suspicious for metastatic head and neck squamous cell carcinoma (commonly from the oropharynx or hypopharynx) and requires urgent ENT referral for panendoscopy and biopsy.', 1),
('c6000000-0000-0000-0000-000000000037', 'B', 'Reassure that this is likely a reactive lymph node from a viral infection and review in 3 months', false, 'Ruled out because a persistent, enlarging, firm, fixed neck lump lasting 3 months with red flag associated symptoms (otalgia, dysphagia) in a high-risk patient should not be assumed reactive; it requires urgent investigation for malignancy.', 2),
('c6000000-0000-0000-0000-000000000037', 'C', 'Prescribe a course of antibiotics for presumed bacterial lymphadenitis', false, 'Ruled out because there is no evidence of acute infection (no fever, tenderness, or rapid onset); the chronic, firm, fixed nature of the node with red flag symptoms points towards malignancy rather than infection.', 3),
('c6000000-0000-0000-0000-000000000037', 'D', 'Arrange routine ultrasound of the neck with results reviewed in 6 weeks', false, 'Ruled out because the red flag clinical features require an urgent, expedited pathway (2-week wait) for specialist assessment, not a routine, delayed imaging pathway.', 4),
('c6000000-0000-0000-0000-000000000037', 'E', 'Perform an open excisional biopsy of the lymph node in primary care', false, 'Ruled out because open excisional biopsy of a suspicious neck node should not be performed outside specialist assessment, as it can complicate subsequent oncological management; urgent ENT referral for proper work-up (including fine needle aspiration and search for a primary tumour) is required instead.', 5),
('c6000000-0000-0000-0000-000000000038', 'A', 'Immediate tonsillectomy', false, 'Ruled out because tonsillectomy is not indicated for a single acute episode of tonsillitis; it is reserved for recurrent, severe episodes meeting specific criteria over time.', 1),
('c6000000-0000-0000-0000-000000000038', 'B', 'Admission for IV antibiotics regardless of clinical severity', false, 'Ruled out because this child has no red flags (no drooling, trismus, or stridor) suggesting a complication such as quinsy or airway compromise, so admission for IV therapy is not required for straightforward tonsillitis.', 2),
('c6000000-0000-0000-0000-000000000038', 'C', 'Acute tonsillitis; manage with analgesia and safety-netting, considering antibiotics based on clinical scoring (e.g. Centor/FeverPAIN criteria) if bacterial cause is likely', true, 'Correct. Bilateral tonsillar swelling with exudate, fever, tender cervical lymphadenopathy, and absence of cough is consistent with acute tonsillitis; most cases are viral and self-limiting, so symptomatic treatment with analgesia is first-line, using clinical scoring systems (Centor or FeverPAIN) to help decide whether antibiotics are likely to benefit a probable bacterial (streptococcal) case.', 3),
('c6000000-0000-0000-0000-000000000038', 'D', 'Reassure with no analgesia as the illness will resolve without any symptomatic treatment', false, 'Ruled out because analgesia is appropriate and helpful for symptomatic relief in tonsillitis, and withholding all treatment is not good practice even in a self-limiting illness.', 4),
('c6000000-0000-0000-0000-000000000038', 'E', 'Arrange same-day ENT referral for consideration of peritonsillar abscess drainage', false, 'Ruled out because there are no features here (trismus, unilateral swelling, uvular deviation, drooling) suggesting a peritonsillar abscess; this is a straightforward case of bilateral tonsillitis.', 5),
('c6000000-0000-0000-0000-000000000039', 'A', 'Simple streptococcal tonsillitis', false, 'Ruled out because the rapid streptococcal test was negative, and the additional features (splenomegaly, posterior cervical nodes, prolonged duration, amoxicillin-induced rash) are specific to infectious mononucleosis rather than isolated streptococcal infection.', 1),
('c6000000-0000-0000-0000-000000000039', 'B', 'Infectious mononucleosis (glandular fever)', true, 'Correct. Severe sore throat with exudative tonsillitis, prolonged duration, posterior cervical lymphadenopathy, splenomegaly, and a characteristic widespread rash after amoxicillin administration are all classic features of infectious mononucleosis, caused by Epstein-Barr virus.', 2),
('c6000000-0000-0000-0000-000000000039', 'C', 'Peritonsillar abscess', false, 'Ruled out because there is no mention of trismus, uvular deviation, or unilateral swelling; the systemic features (splenomegaly, posterior lymphadenopathy, rash after amoxicillin) point to infectious mononucleosis instead.', 3),
('c6000000-0000-0000-0000-000000000039', 'D', 'Amoxicillin allergy (true penicillin allergy)', false, 'Ruled out because the rash following amoxicillin in infectious mononucleosis is a well-recognised non-allergic drug reaction related to the underlying EBV infection, not necessarily indicating a true penicillin allergy.', 4),
('c6000000-0000-0000-0000-000000000039', 'E', 'Diphtheria', false, 'Ruled out because diphtheria classically causes a grey adherent pseudomembrane and is now extremely rare in vaccinated populations; the clinical picture here (splenomegaly, posterior cervical nodes, amoxicillin rash) is much more consistent with infectious mononucleosis.', 5),
('c6000000-0000-0000-0000-000000000040', 'A', 'Branchial cyst', false, 'Ruled out because branchial cysts typically present as lateral (not midline) neck swellings, usually anterior to the sternocleidomastoid muscle, and do not move with swallowing or tongue protrusion.', 1),
('c6000000-0000-0000-0000-000000000040', 'B', 'Reactive cervical lymphadenopathy', false, 'Ruled out because reactive lymph nodes are typically lateral, do not move with tongue protrusion, and are not fluctuant midline congenital swellings present since birth.', 2),
('c6000000-0000-0000-0000-000000000040', 'C', 'Cystic hygroma (lymphangioma)', false, 'Ruled out because cystic hygromas are typically soft, transilluminating, multiloculated swellings most often found in the posterior triangle of the neck, not midline swellings that move with tongue protrusion.', 3),
('c6000000-0000-0000-0000-000000000040', 'D', 'Thyroglossal duct cyst', true, $x$Correct. A midline neck swelling that moves upward on swallowing and tongue protrusion, present since birth, with recurrent episodes of infection, is the classic description of a thyroglossal duct cyst, a remnant of the thyroglossal duct's embryological descent; definitive management is surgical excision (Sistrunk procedure) after infection has settled.$x$, 4),
('c6000000-0000-0000-0000-000000000040', 'E', 'Dermoid cyst', false, 'Ruled out because although dermoid cysts can occur in the midline, they do not characteristically move with swallowing and tongue protrusion in the way described, which is the specific hallmark of a thyroglossal duct cyst.', 5),
('c6000000-0000-0000-0000-000000000041', 'A', 'Reassure with no further action needed regardless of duration', false, 'Ruled out because although this is likely benign, persistent hoarseness beyond 3-6 weeks should still prompt laryngoscopic assessment to directly visualise the larynx and exclude other causes, rather than being dismissed indefinitely without ever examining the vocal cords.', 1),
('c6000000-0000-0000-0000-000000000041', 'B', 'Referral for flexible nasendoscopy/laryngoscopy if hoarseness persists beyond a total of 3-6 weeks, alongside speech and language therapy advice on voice care', true, 'Correct. Hoarseness following vocal overuse in a young non-smoker without red flag features (no dysphagia, weight loss, neck lump) is likely due to a benign cause such as vocal cord nodules from voice misuse/overuse; however, any hoarseness persisting beyond the typical 3-6 week guideline threshold should still be assessed with laryngoscopy to visualise the vocal cords and exclude other pathology, alongside voice care advice/speech and language therapy input.', 2),
('c6000000-0000-0000-0000-000000000041', 'C', 'Immediate CT neck and chest as first-line investigation', false, 'Ruled out because the first step in persistent hoarseness is direct visualisation of the vocal cords via laryngoscopy, not cross-sectional imaging, which would only be considered based on laryngoscopy findings.', 3),
('c6000000-0000-0000-0000-000000000041', 'D', 'Empirical course of oral corticosteroids for the hoarseness', false, 'Ruled out because oral corticosteroids are not standard management for benign vocal cord nodules or overuse-related hoarseness; voice rest, voice therapy, and appropriate assessment are the correct approach.', 4),
('c6000000-0000-0000-0000-000000000041', 'E', 'Urgent same-day ENT referral given the risk of laryngeal cancer', false, 'Ruled out because there are no red flag features here (young age, non-smoker, no dysphagia/weight loss/neck lump, clear precipitating cause of voice overuse), so this does not need to be treated as an urgent cancer-pathway referral, though persistent hoarseness beyond the guideline threshold still warrants laryngoscopy.', 5),
('c6000000-0000-0000-0000-000000000042', 'A', $x$Warthin's tumour$x$, false, $x$Ruled out because although Warthin's tumour is also a benign parotid tumour and can present similarly, it is classically associated with older male smokers and can be bilateral; pleomorphic adenoma remains the most common overall parotid tumour and the most likely single best answer here given no smoking history or bilaterality mentioned.$x$, 1),
('c6000000-0000-0000-0000-000000000042', 'B', 'Parotid malignancy (e.g. mucoepidermoid carcinoma)', false, 'Ruled out because the absence of facial nerve weakness, pain, rapid growth, or skin fixation makes malignancy less likely than benign pleomorphic adenoma, though malignancy must still be excluded histologically after excision.', 2),
('c6000000-0000-0000-0000-000000000042', 'C', 'Pleomorphic adenoma', true, 'Correct. A slow-growing, painless, smooth, mobile parotid mass without facial nerve involvement is the classic presentation of a pleomorphic adenoma, the most common benign salivary gland tumour; management is surgical excision (superficial or partial parotidectomy) due to a small risk of malignant transformation if left untreated, with care taken to preserve the facial nerve.', 3),
('c6000000-0000-0000-0000-000000000042', 'D', 'Sialadenitis (acute parotitis)', false, 'Ruled out because sialadenitis typically presents acutely with pain, swelling, and tenderness, often with fever, rather than a gradually enlarging painless mass over 2 months.', 4),
('c6000000-0000-0000-0000-000000000042', 'E', 'Reactive preauricular lymphadenopathy', false, 'Ruled out because a slowly enlarging, smooth, mobile mass within the parotid gland itself over 2 months is more consistent with a salivary gland neoplasm than a reactive lymph node.', 5),
('c6000000-0000-0000-0000-000000000043', 'A', 'Submandibular gland sialolithiasis (salivary duct stone)', true, 'Correct. Recurrent pain and swelling of the submandibular gland precipitated by eating (mealtime syndrome), with a palpable hard mass along the duct in the floor of the mouth, is characteristic of sialolithiasis, most commonly affecting the submandibular gland due to its duct anatomy (longer, more upward course against gravity, and more viscous, alkaline saliva).', 1),
('c6000000-0000-0000-0000-000000000043', 'B', 'Acute bacterial sialadenitis unrelated to any stone', false, 'Ruled out because the classic pattern of pain and swelling specifically triggered by eating, with a palpable hard mass in the duct, points to an obstructing stone (which can secondarily cause infection) rather than isolated infection without obstruction.', 2),
('c6000000-0000-0000-0000-000000000043', 'C', $x$Sjogren's syndrome$x$, false, $x$Ruled out because Sjogren's syndrome typically causes persistent dry mouth and dry eyes with gradual, often bilateral gland swelling, not acute recurrent pain triggered by eating with a palpable ductal mass.$x$, 3),
('c6000000-0000-0000-0000-000000000043', 'D', 'Pleomorphic adenoma of the submandibular gland', false, 'Ruled out because pleomorphic adenoma presents as a slow-growing, painless mass, not recurrent acute pain and swelling specifically related to meals with a palpable stone in the duct.', 4),
('c6000000-0000-0000-0000-000000000043', 'E', $x$Ludwig's angina$x$, false, $x$Ruled out because Ludwig's angina is a rapidly progressive, bilateral, board-like cellulitis of the floor of mouth causing airway compromise, not intermittent, recurrent, meal-related swelling with a palpable discrete ductal stone.$x$, 5),
('c6000000-0000-0000-0000-000000000044', 'A', 'Simple gastro-oesophageal reflux disease exacerbation', false, 'Ruled out because simple reflux does not typically cause regurgitation of undigested food, gurgling neck noises, or halitosis; these specific features point to a structural abnormality such as a pharyngeal pouch.', 1),
('c6000000-0000-0000-0000-000000000044', 'B', 'Oesophageal candidiasis', false, 'Ruled out because oesophageal candidiasis typically causes odynophagia in immunocompromised patients, not the specific combination of regurgitated undigested food, neck gurgling, and halitosis described here.', 2),
('c6000000-0000-0000-0000-000000000044', 'C', 'Achalasia', false, $x$Ruled out because although achalasia causes progressive dysphagia and regurgitation, it does not typically cause the specific gurgling neck noise or halitosis associated with a pharyngeal pouch, and is usually confirmed with manometry/barium studies showing a 'bird's beak' oesophagus rather than a posterior pharyngeal outpouching.$x$, 3),
('c6000000-0000-0000-0000-000000000044', 'D', $x$Pharyngeal pouch (Zenker's diverticulum)$x$, true, $x$Correct. Progressive dysphagia with regurgitation of undigested food, gurgling neck noises on swallowing, and halitosis in an older patient is characteristic of a pharyngeal pouch (Zenker's diverticulum), an outpouching through Killian's dehiscence in the posterior pharyngeal wall; however, given the progressive dysphagia and weight loss, malignancy must also be actively excluded (typically via barium swallow and/or endoscopy) as part of the same urgent work-up.$x$, 4),
('c6000000-0000-0000-0000-000000000044', 'E', 'Globus pharyngeus', false, 'Ruled out because globus pharyngeus is a sensation of a lump in the throat without true dysphagia, weight loss, or regurgitation of food, which are all present in this progressive, red-flag presentation.', 5),
('c6000000-0000-0000-0000-000000000045', 'A', 'Oesophageal carcinoma', false, 'Ruled out because oesophageal carcinoma causes true progressive dysphagia (difficulty actually swallowing food/liquid) and weight loss, neither of which are present here; the symptom pattern (relieved by eating/distraction) is inconsistent with a structural obstructing lesion.', 1),
('c6000000-0000-0000-0000-000000000045', 'B', $x$Pharyngeal pouch (Zenker's diverticulum)$x$, false, 'Ruled out because a pharyngeal pouch causes true dysphagia with regurgitation of food and halitosis, not simply a sensation of a lump that varies with anxiety and is relieved by eating.', 2),
('c6000000-0000-0000-0000-000000000045', 'C', 'Laryngopharyngeal reflux', false, 'Ruled out because although reflux can contribute to globus-type sensations in some patients, the classic pattern described here (relief with eating/distraction, clear anxiety association, entirely normal examination, no true dysphagia) is most consistent with globus pharyngeus as a functional diagnosis rather than reflux being highlighted as the primary answer.', 3),
('c6000000-0000-0000-0000-000000000045', 'D', 'Thyroid malignancy', false, 'Ruled out because there is no palpable neck mass or thyroid abnormality described, and thyroid malignancy does not typically present solely with an anxiety-related globus sensation with no other findings.', 4),
('c6000000-0000-0000-0000-000000000045', 'E', 'Globus pharyngeus', true, 'Correct. A persistent sensation of a lump in the throat without true dysphagia (normal swallowing of solids and liquids), which improves with distraction/eating and worsens with anxiety, in a patient with a background of anxiety and a normal examination, is characteristic of globus pharyngeus, a functional sensation; this diagnosis is made after excluding organic causes, particularly if red flags are absent.', 5),
('c6000000-0000-0000-0000-000000000046', 'A', 'Discharge home with oral antibiotics only', false, 'Ruled out because this child is systemically unwell (high fever, reduced oral intake) with a confirmed abscess, requiring admission for IV antibiotics and close monitoring rather than outpatient oral treatment alone.', 1),
('c6000000-0000-0000-0000-000000000046', 'B', 'Immediate incision and drainage without any trial of antibiotics', false, 'Ruled out because a trial of IV antibiotics is generally appropriate first for suppurative lymphadenitis, with surgical drainage reserved for cases that fail to improve or continue enlarging, rather than surgery being the automatic first step in every case.', 2),
('c6000000-0000-0000-0000-000000000046', 'C', 'Reassure that this will resolve without any treatment as it follows a viral infection', false, 'Ruled out because a discrete abscess with systemic illness will not reliably resolve without treatment and risks further complications (spread, airway compromise) if untreated.', 3),
('c6000000-0000-0000-0000-000000000046', 'D', 'Arrange outpatient ultrasound-guided aspiration in 2 weeks', false, 'Ruled out because this child is acutely unwell with a confirmed collection now and needs prompt admission and treatment, not a delayed outpatient plan.', 4),
('c6000000-0000-0000-0000-000000000046', 'E', 'Admission for IV antibiotics with surgical/ENT input for possible incision and drainage if it fails to settle or enlarges', true, 'Correct. A rapidly enlarging, tender, fluctuant cervical lymph node with systemic illness following a recent infection, confirmed as a discrete abscess on ultrasound, represents suppurative cervical lymphadenitis; management requires admission for IV antibiotics with surgical/ENT review, as incision and drainage may be needed if it does not respond to antibiotics alone or continues to enlarge.', 5),
('c6000000-0000-0000-0000-000000000047', 'A', 'Urgent ENT referral for same-day removal', false, 'Ruled out because simple cerumen impaction without red flags (perforation, infection, recent surgery, immunocompromise) does not require urgent specialist referral; it is appropriately managed in primary care with softening drops +/- irrigation or microsuction.', 1),
('c6000000-0000-0000-0000-000000000047', 'B', 'Reassure that the hearing loss will resolve without any intervention', false, 'Ruled out because a canal fully occluded by wax will not typically clear spontaneously and is actively causing conductive hearing loss; treatment with softening agents and removal is appropriate.', 2),
('c6000000-0000-0000-0000-000000000047', 'C', 'Trial of ear drops (e.g. olive oil or sodium bicarbonate) to soften the wax, with consideration of irrigation or microsuction if this fails', true, 'Correct. Unilateral conductive hearing loss with a canal fully occluded by wax and no red flags (no pain, discharge, perforation history, or recent ear surgery) is simply managed with wax-softening drops in the first instance, followed by irrigation or microsuction if the wax does not clear, rather than more invasive or urgent measures.', 3),
('c6000000-0000-0000-0000-000000000047', 'D', 'Arrange MRI of the internal auditory meatus to exclude a retrocochlear lesion', false, 'Ruled out because the hearing loss here is clearly conductive and explained by visible wax completely occluding the canal, not an unexplained sensorineural loss that would warrant MRI.', 4),
('c6000000-0000-0000-0000-000000000047', 'E', 'Advise the patient to insert a cotton bud to remove the wax herself', false, 'Ruled out because cotton bud use itself is a cause of wax impaction (pushing wax further in) and canal trauma, and should be actively discouraged rather than recommended.', 5),
('c6000000-0000-0000-0000-000000000048', 'A', 'Urgent assessment for suspected CSF rhinorrhoea, avoiding nasal packing, with neurosurgical/ENT input and appropriate imaging', true, 'Correct. Clear watery nasal discharge after head trauma, worse on leaning forward, raises strong suspicion of cerebrospinal fluid (CSF) rhinorrhoea from a skull base (anterior cranial fossa) fracture; nasal packing should be avoided as it can force pathogens into the CSF/intracranial space, and urgent neurosurgical/ENT assessment with appropriate imaging (CT) is required, along with monitoring for signs of meningitis.', 1),
('c6000000-0000-0000-0000-000000000048', 'B', 'Insert bilateral anterior nasal packs to stop the discharge', false, 'Ruled out because nasal packing in suspected CSF rhinorrhoea should be avoided, as it can increase the risk of ascending infection (meningitis) and does not address the underlying skull base defect.', 2),
('c6000000-0000-0000-0000-000000000048', 'C', 'Reassure that this is simple post-traumatic rhinorrhoea and discharge with safety-netting', false, 'Ruled out because the described features (clear fluid, worse on leaning forward, associated significant head trauma) are concerning for a CSF leak, which requires urgent specialist assessment, not reassurance and discharge.', 3),
('c6000000-0000-0000-0000-000000000048', 'D', 'Prescribe oral decongestants and review in one week', false, 'Ruled out because decongestants do not address a potential skull base fracture with CSF leak, and delaying assessment increases the risk of undetected meningitis or ongoing leak.', 4),
('c6000000-0000-0000-0000-000000000048', 'E', 'Perform nasal endoscopy immediately at the bedside without imaging', false, 'Ruled out because instrumenting the nose in a suspected skull base fracture/CSF leak risks introducing infection or causing further trauma before imaging has characterised the injury; initial priority is urgent imaging and specialist referral, not unsupervised bedside endoscopy.', 5),
('c6000000-0000-0000-0000-000000000049', 'A', 'Allergic rhinitis', false, 'Ruled out because allergic rhinitis typically causes bilateral symptoms with sneezing, itching, and clear discharge, and would show pale swollen mucosa, not a fixed structural deviation with otherwise normal mucosa.', 1),
('c6000000-0000-0000-0000-000000000049', 'B', 'Deviated nasal septum', true, 'Correct. Long-standing, one-sided nasal obstruction following previous nasal trauma, with a visibly deviated septum on examination and no evidence of mucosal inflammation, discharge, or polyps, is characteristic of a structural deviated nasal septum causing mechanical airflow obstruction.', 2),
('c6000000-0000-0000-0000-000000000049', 'C', 'Chronic rhinosinusitis with nasal polyps', false, 'Ruled out because there are no polyps seen on examination and no discharge or anosmia described; the fixed unilateral obstruction with a visibly deviated septum points to a structural cause.', 3),
('c6000000-0000-0000-0000-000000000049', 'D', 'Adenoidal hypertrophy', false, 'Ruled out because adenoidal hypertrophy is a cause of nasal obstruction predominantly in children, not adults, and would not be identified as a deviated septum on anterior rhinoscopy.', 4),
('c6000000-0000-0000-0000-000000000049', 'E', 'Rhinitis medicamentosa', false, 'Ruled out because there is no history of chronic decongestant spray overuse described, and the fixed, structural, post-traumatic nature of the deviation is a better explanation than a reversible mucosal rebound phenomenon.', 5),
('c6000000-0000-0000-0000-000000000050', 'A', 'Immediate total thyroidectomy', false, 'Ruled out because surgery is not the first step for an asymptomatic, euthyroid, diffuse goitre without red flag features; further characterisation with ultrasound (and biopsy if a suspicious nodule is found) precedes any decision about surgical management.', 1),
('c6000000-0000-0000-0000-000000000050', 'B', 'Radioactive iodine uptake scan as the first-line investigation', false, 'Ruled out because radioiodine uptake scanning is used to assess thyroid function/nodule activity (e.g. in hyperthyroidism), not as the first investigation for a diffuse goitre with normal thyroid function tests; ultrasound is the appropriate initial imaging step.', 2),
('c6000000-0000-0000-0000-000000000050', 'C', 'Reassure with no further investigation as thyroid function is normal', false, 'Ruled out because a new, gradually enlarging goitre still warrants imaging (ultrasound) to characterise its structure and exclude a nodule, even though thyroid function itself is normal.', 3),
('c6000000-0000-0000-0000-000000000050', 'D', 'Ultrasound of the thyroid gland', true, 'Correct. A painless, diffuse, smooth goitre that moves on swallowing, with normal thyroid function and no red flag features, is appropriately further characterised with thyroid ultrasound, which helps assess gland structure and identify any discrete nodules that might need further sampling (fine needle aspiration), even when the goitre appears diffuse on examination.', 4),
('c6000000-0000-0000-0000-000000000050', 'E', 'Start empirical levothyroxine to shrink the goitre', false, 'Ruled out because levothyroxine is not indicated when thyroid function is normal (euthyroid); it does not have a proven role in shrinking a simple goitre and should not be given empirically.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c6000000-0000-0000-0000-000000000001', 'First aid for epistaxis: sit forward, pinch the soft cartilaginous part of the nose (not the bony bridge) continuously for 10-15 minutes.', 1),
('c6000000-0000-0000-0000-000000000001', 'If first aid fails, examine for a visible bleeding point (cautery with silver nitrate if found) before proceeding to anterior nasal packing.', 2),
('c6000000-0000-0000-0000-000000000001', $x$Most epistaxis arises from Little's area (Kiesselbach's plexus) on the anterior nasal septum.$x$, 3),
('c6000000-0000-0000-0000-000000000002', 'In choking, distinguish effective cough (encourage coughing, stay with patient) from ineffective cough (unable to vocalise, silent/weakening cough, cyanosis, decreasing consciousness) which needs active intervention.', 1),
('c6000000-0000-0000-0000-000000000002', 'Paediatric choking algorithm: conscious child with ineffective cough gets up to 5 back blows, then up to 5 abdominal thrusts (chest thrusts in infants), reassessing between each.', 2),
('c6000000-0000-0000-0000-000000000002', 'Blind finger sweeps are avoided as they can worsen obstruction; visualised removal under direct vision (laryngoscopy) is preferred if the object is seen.', 3),
('c6000000-0000-0000-0000-000000000003', $x$Epiglottitis classically presents with rapid-onset fever, sore throat, drooling, muffled 'hot potato' voice, and tripod positioning, most often in unvaccinated children (Haemophilus influenzae type b).$x$, 1),
('c6000000-0000-0000-0000-000000000003', 'Do not examine the throat or distress a child with suspected epiglottitis outside a controlled airway setting - this can precipitate complete obstruction.', 2),
('c6000000-0000-0000-0000-000000000003', 'Management requires urgent senior anaesthetic and ENT involvement to secure the airway, typically in theatre, followed by IV antibiotics.', 3),
('c6000000-0000-0000-0000-000000000004', 'Quinsy (peritonsillar abscess) classically causes trismus, muffled voice, unilateral peritonsillar bulge, and uvular deviation away from the affected side.', 1),
('c6000000-0000-0000-0000-000000000004', 'Management is urgent ENT referral for needle aspiration or incision and drainage, plus IV antibiotics and analgesia.', 2),
('c6000000-0000-0000-0000-000000000004', $x$Distinguish quinsy from simple tonsillitis (bilateral, no trismus or uvular deviation) and from deeper space infections such as retropharyngeal abscess or Ludwig's angina.$x$, 3),
('c6000000-0000-0000-0000-000000000005', $x$The 'can't intubate, can't ventilate' scenario is a recognised difficult airway emergency requiring immediate escalation to front-of-neck access (cricothyroidotomy) when basic and advanced airway manoeuvres fail.$x$, 1),
('c6000000-0000-0000-0000-000000000005', 'Difficult Airway Society algorithms emphasise early declaration of a failed airway and rapid progression to surgical airway rescue rather than repeated failed attempts.', 2),
('c6000000-0000-0000-0000-000000000005', 'Delaying definitive airway rescue in a hypoxic, unconscious patient risks hypoxic brain injury and cardiac arrest.', 3),
('c6000000-0000-0000-0000-000000000006', 'Malignant (necrotising) otitis externa should be suspected in diabetic or immunocompromised patients with severe, persistent otitis externa, disproportionate pain, granulation tissue, and cranial nerve involvement (especially facial nerve).', 1),
('c6000000-0000-0000-0000-000000000006', 'The most common causative organism is Pseudomonas aeruginosa; management requires urgent ENT referral, imaging (CT/MRI), and prolonged systemic antipseudomonal antibiotics.', 2),
('c6000000-0000-0000-0000-000000000006', 'Facial nerve palsy or other cranial neuropathy in this context signals skull base osteomyelitis and is a red flag requiring urgent escalation, not reassurance.', 3),
('c6000000-0000-0000-0000-000000000007', 'Septal haematoma after nasal trauma appears as a bilateral bluish, fluctuant swelling of the septum and is an emergency requiring same-day incision and drainage.', 1),
('c6000000-0000-0000-0000-000000000007', 'Untreated septal haematoma causes ischaemic necrosis of the septal cartilage, leading to saddle-nose deformity, or can become infected forming a septal abscess.', 2),
('c6000000-0000-0000-0000-000000000007', 'This differs from a simple nasal bone fracture, which can often be safely reviewed in a delayed fracture clinic once swelling has settled.', 3),
('c6000000-0000-0000-0000-000000000008', 'Croup severity is assessed clinically: mild (occasional barking cough, no stridor at rest) vs moderate (stridor at rest, some recession, but alert) vs severe (marked distress, agitation/lethargy, cyanosis).', 1),
('c6000000-0000-0000-0000-000000000008', 'Oral dexamethasone is first-line for all but the mildest croup; nebulised adrenaline plus high-dose steroids and senior/anaesthetic input is used for severe croup.', 2),
('c6000000-0000-0000-0000-000000000008', 'Croup is usually caused by parainfluenza virus and is self-limiting, but steroids reduce symptom severity and healthcare re-attendance.', 3),
('c6000000-0000-0000-0000-000000000009', $x$Ludwig's angina is a bilateral, rapidly spreading cellulitis of the submandibular and sublingual spaces, usually from dental infection, causing tongue elevation, trismus, and airway compromise.$x$, 1),
('c6000000-0000-0000-0000-000000000009', 'Developing stridor or voice change indicates impending airway obstruction and requires urgent senior anaesthetic/ENT/maxillofacial involvement for a controlled, secured airway before the situation becomes critical.', 2),
('c6000000-0000-0000-0000-000000000009', $x$Unlike a peritonsillar abscess, Ludwig's angina is typically a diffuse, board-like cellulitis rather than a discrete fluctuant collection, and IV antibiotics plus airway control take priority over blind bedside drainage.$x$, 3),
('c6000000-0000-0000-0000-000000000010', 'The HINTS examination (Head Impulse, Nystagmus, Test of Skew) helps differentiate peripheral (vestibular neuritis/labyrinthitis) from central (stroke) causes of acute vestibular syndrome.', 1),
('c6000000-0000-0000-0000-000000000010', 'An abnormal head impulse test with unidirectional, fixation-suppressed nystagmus and no skew deviation favours a peripheral vestibular cause.', 2),
('c6000000-0000-0000-0000-000000000010', 'Absence of hearing loss distinguishes vestibular neuritis from labyrinthitis (which also affects hearing); red flags for a central cause include normal head impulse test, direction-changing nystagmus, or additional neurological signs, which should prompt urgent stroke work-up.', 3),
('c6000000-0000-0000-0000-000000000011', 'Retropharyngeal abscess is more common in young children, often following a preceding upper respiratory tract infection, and presents with fever, neck stiffness/torticollis, drooling, and reluctance to move the neck.', 1),
('c6000000-0000-0000-0000-000000000011', 'Widening of the prevertebral soft tissue space on lateral neck X-ray supports the diagnosis, but CT neck with contrast is used to confirm and delineate the abscess before definitive management.', 2),
('c6000000-0000-0000-0000-000000000011', 'Management requires urgent ENT input, IV antibiotics, and often surgical drainage given the risk of airway compromise or mediastinal spread.', 3),
('c6000000-0000-0000-0000-000000000012', 'Posterior epistaxis should be suspected when bleeding continues into the oropharynx despite an adequately placed anterior nasal pack.', 1),
('c6000000-0000-0000-0000-000000000012', 'Posterior bleeds are often heavier, harder to control, and more likely to require balloon tamponade, postnasal packing, or surgical/radiological intervention (e.g. arterial ligation or embolisation) under ENT care.', 2),
('c6000000-0000-0000-0000-000000000012', 'Escalate promptly rather than repeating or removing a failed technique, especially as posterior bleeds carry a higher risk of airway compromise and haemodynamic instability.', 3),
('c6000000-0000-0000-0000-000000000013', 'Unilateral foul-smelling or blood-stained nasal discharge in a young child should always raise suspicion of a retained nasal foreign body.', 1),
('c6000000-0000-0000-0000-000000000013', 'Nasal foreign bodies should be removed promptly by an experienced clinician; button batteries in particular require urgent same-day removal due to the risk of rapid caustic tissue injury.', 2),
('c6000000-0000-0000-0000-000000000013', 'Avoid pushing foreign bodies further in with irrigation or blind instrumentation; if removal is not straightforward, ENT referral is appropriate.', 3),
('c6000000-0000-0000-0000-000000000014', 'Uncomplicated acute otitis media in an otherwise well child is usually managed with analgesia and a watch-and-wait approach rather than immediate antibiotics.', 1),
('c6000000-0000-0000-0000-000000000014', 'Indications to consider antibiotics include symptoms lasting more than 2-3 days without improvement, systemic illness, otorrhoea, bilateral disease in children under 2, or immunocompromise.', 2),
('c6000000-0000-0000-0000-000000000014', 'Red flags requiring urgent escalation include persistent high fever, severe pain, mastoid swelling/tenderness (suggesting mastoiditis), or signs of intracranial complication.', 3),
('c6000000-0000-0000-0000-000000000015', 'Unilateral or asymmetric sensorineural hearing loss, especially with tinnitus, imbalance, or facial/trigeminal symptoms, should raise suspicion of a vestibular schwannoma and prompt MRI of the internal auditory meatus with contrast.', 1),
('c6000000-0000-0000-0000-000000000015', 'Vestibular schwannomas arise from the vestibular portion of the eighth cranial nerve within the cerebellopontine angle and can compress adjacent cranial nerves (V, VII) as they grow.', 2),
('c6000000-0000-0000-0000-000000000015', 'This differs from presbycusis, which is typically bilateral, symmetric, high-frequency sensorineural hearing loss without focal neurological features.', 3),
('c6000000-0000-0000-0000-000000000016', 'Otitis externa classically causes tragal/pinna tenderness on movement, canal erythema and swelling, and is associated with water exposure (swimming) or trauma (cotton bud use).', 1),
('c6000000-0000-0000-0000-000000000016', 'First-line treatment is typically topical antibiotic +/- steroid ear drops, with advice to keep the ear dry.', 2),
('c6000000-0000-0000-0000-000000000016', 'Distinguish from malignant otitis externa (in diabetics/immunocompromised, with disproportionate pain and possible cranial nerve palsy) which needs urgent escalation.', 3),
('c6000000-0000-0000-0000-000000000017', 'Cholesteatoma classically causes chronic painless foul-smelling otorrhoea and conductive hearing loss, with a retraction pocket (often postero-superior) or attic defect containing keratin debris on otoscopy.', 1),
('c6000000-0000-0000-0000-000000000017', 'Cholesteatoma can erode the ossicles, bony labyrinth, or facial nerve canal if untreated, so ENT referral for further assessment (imaging, surgical removal) is required.', 2),
('c6000000-0000-0000-0000-000000000017', 'This differs from otosclerosis, which causes conductive hearing loss due to stapes fixation with a normal-looking tympanic membrane and no discharge.', 3),
('c6000000-0000-0000-0000-000000000018', 'Presbycusis is the most common cause of hearing loss in older adults: bilateral, symmetric, gradually progressive, high-frequency sensorineural hearing loss with a normal otoscopic examination.', 1),
('c6000000-0000-0000-0000-000000000018', 'Management includes hearing assessment (audiometry) and hearing aids if the loss is significantly affecting quality of life; there is no reversible underlying pathology to treat.', 2),
('c6000000-0000-0000-0000-000000000018', $x$Distinguish from conductive causes (otosclerosis, effusion) which show abnormal otoscopy or air-bone gap on audiometry, and from Meniere's disease which is episodic with vertigo.$x$, 3),
('c6000000-0000-0000-0000-000000000019', $x$Meniere's disease presents with recurrent episodic vertigo (20 minutes to several hours), fluctuating sensorineural hearing loss (classically low-frequency), tinnitus, and aural fullness.$x$, 1),
('c6000000-0000-0000-0000-000000000019', 'It is thought to result from excess endolymph fluid (endolymphatic hydrops) within the inner ear.', 2),
('c6000000-0000-0000-0000-000000000019', 'Management includes lifestyle/dietary advice (low salt), betahistine, and specialist referral; hearing loss can become permanent and progressive over time despite symptom control between attacks.', 3),
('c6000000-0000-0000-0000-000000000020', 'BPPV causes brief (seconds to about a minute), positional vertigo triggered by specific head movements, diagnosed with a positive Dix-Hallpike test showing rotatory nystagmus that fatigues with repetition.', 1),
('c6000000-0000-0000-0000-000000000020', 'The Epley manoeuvre is the first-line treatment, aiming to reposition displaced otoconia (canalith debris) out of the semicircular canal.', 2),
('c6000000-0000-0000-0000-000000000020', $x$Absence of hearing loss or tinnitus helps distinguish BPPV from Meniere's disease and other inner ear pathology.$x$, 3),
('c6000000-0000-0000-0000-000000000021', 'Otosclerosis causes progressive conductive hearing loss due to abnormal bone remodelling fixing the stapes footplate, typically presenting in young adults with an autosomal dominant family history.', 1),
('c6000000-0000-0000-0000-000000000021', 'Paracusis willisii (hearing better in noisy surroundings) and exacerbation during pregnancy are classic clinical clues to otosclerosis.', 2),
('c6000000-0000-0000-0000-000000000021', 'A Carhart notch (dip at 2000 Hz) on audiometry with a normal tympanic membrane supports the diagnosis; management options include hearing aids or stapedectomy/stapedotomy surgery.', 3),
('c6000000-0000-0000-0000-000000000022', 'Sudden sensorineural hearing loss (SSNHL) is defined as a loss of at least 30 dB across 3 consecutive frequencies occurring within 72 hours and is an otological emergency.', 1),
('c6000000-0000-0000-0000-000000000022', 'Urgent ENT referral is required, as oral or intratympanic corticosteroids started early (ideally within 2 weeks) give the best chance of hearing recovery.', 2),
('c6000000-0000-0000-0000-000000000022', 'Most cases are idiopathic, but red flags (focal neurology, associated features) should prompt consideration of alternative causes such as stroke or acoustic neuroma via MRI.', 3),
('c6000000-0000-0000-0000-000000000023', 'Otitis media with effusion (glue ear) is a common cause of conductive hearing loss in children, often picked up incidentally or via school screening, with a dull/retracted drum, visible fluid level, and flat (type B) tympanometry.', 1),
('c6000000-0000-0000-0000-000000000023', 'Many cases resolve spontaneously within 3 months; persistent bilateral effusion causing significant hearing loss or developmental/speech concerns may warrant ENT referral for consideration of grommets.', 2),
('c6000000-0000-0000-0000-000000000023', 'Distinguish from acute otitis media, which is painful and acutely inflamed, and from cholesteatoma, which causes chronic discharge with keratin debris.', 3),
('c6000000-0000-0000-0000-000000000024', 'Ramsay Hunt syndrome (herpes zoster oticus) presents with lower motor neurone facial palsy plus severe ear pain, a vesicular rash in the ear canal/pinna, and often hearing loss or tinnitus.', 1),
('c6000000-0000-0000-0000-000000000024', 'Prompt treatment with oral antivirals (e.g. aciclovir) and corticosteroids, ideally within 72 hours of onset, improves the chance of facial nerve recovery.', 2),
('c6000000-0000-0000-0000-000000000024', $x$Distinguish from Bell's palsy (no rash, no otalgia) and from stroke (upper motor neurone pattern sparing the forehead, associated with other central neurological signs).$x$, 3),
('c6000000-0000-0000-0000-000000000025', 'Ear canal foreign bodies away from the tympanic membrane in a cooperative child can often be removed at first attempt by an experienced clinician using appropriate technique.', 1),
('c6000000-0000-0000-0000-000000000025', 'Button batteries and organic material (e.g. seeds, which can swell) require particular caution; irrigation is avoided for batteries and disc magnets due to tissue injury risk.', 2),
('c6000000-0000-0000-0000-000000000025', 'If removal is unsuccessful, causes distress, or risks trauma, referral to ENT (sometimes for removal under general anaesthetic) is appropriate rather than repeated forceful attempts.', 3),
('c6000000-0000-0000-0000-000000000026', 'Acute rhinosinusitis is most often viral and self-limiting; symptomatic treatment with analgesia and nasal saline is first-line.', 1),
('c6000000-0000-0000-0000-000000000026', 'Antibiotics are reserved for symptoms persisting beyond 10 days without improvement, or marked systemic illness/high complication risk.', 2),
('c6000000-0000-0000-0000-000000000026', 'Red flags requiring urgent escalation include periorbital swelling, visual changes, severe frontal headache, or altered consciousness, suggesting orbital or intracranial spread of infection.', 3),
('c6000000-0000-0000-0000-000000000027', 'Orbital cellulitis (infection posterior to the orbital septum) is distinguished from preseptal cellulitis by painful/restricted eye movements, proptosis, and reduced visual acuity - all are red flags requiring emergency management.', 1),
('c6000000-0000-0000-0000-000000000027', 'It is a recognised complication of sinusitis (especially ethmoiditis) and requires urgent admission, IV antibiotics, contrast CT imaging, and joint ENT/ophthalmology care.', 2),
('c6000000-0000-0000-0000-000000000027', 'Preseptal cellulitis, in contrast, has normal eye movements and vision and can often be managed with oral antibiotics, but must be carefully distinguished from the more dangerous orbital form.', 3),
('c6000000-0000-0000-0000-000000000028', 'Allergic rhinitis presents with sneezing, clear rhinorrhoea, nasal congestion, and itchy/watery eyes, often with a seasonal pattern (pollen) or perennial pattern (house dust mite, pets) and personal/family history of atopy.', 1),
('c6000000-0000-0000-0000-000000000028', 'First-line management includes allergen avoidance, intranasal corticosteroids, and oral or intranasal antihistamines.', 2),
('c6000000-0000-0000-0000-000000000028', $x$Pale, swollen ('boggy') nasal mucosa on examination is typical of allergic rhinitis, contrasting with the polyps seen in chronic rhinosinusitis with nasal polyposis.$x$, 3),
('c6000000-0000-0000-0000-000000000029', $x$Nasal polyps present as bilateral, pale, grape-like, mobile, insensate masses causing nasal obstruction and anosmia, and are associated with chronic rhinosinusitis, asthma, and aspirin sensitivity (Samter's/aspirin-exacerbated respiratory disease triad).$x$, 1),
('c6000000-0000-0000-0000-000000000029', 'Management includes intranasal or oral corticosteroids, with surgery (functional endoscopic sinus surgery) for cases refractory to medical treatment.', 2),
('c6000000-0000-0000-0000-000000000029', 'Unilateral, unusual-looking, bleeding, or rapidly growing nasal masses warrant biopsy/further investigation to exclude sinonasal malignancy, unlike typical bilateral polyps.', 3),
('c6000000-0000-0000-0000-000000000030', 'Red flags for sinonasal malignancy include unilateral nasal obstruction, blood-stained discharge, facial pain/numbness (cranial nerve involvement), and unexplained weight loss.', 1),
('c6000000-0000-0000-0000-000000000030', 'Unilateral, firm, irregular, or bleeding nasal masses should never be assumed to be simple polyps and require urgent ENT referral with biopsy to exclude malignancy.', 2),
('c6000000-0000-0000-0000-000000000030', 'Facial numbness in this context suggests infraorbital nerve involvement, indicating local tumour invasion and the need for prompt cross-sectional imaging and histological diagnosis.', 3),
('c6000000-0000-0000-0000-000000000031', 'Uncomplicated nasal fractures are best assessed for deformity after initial swelling has settled (around 5-7 days), as early swelling can mask or mimic deformity.', 1),
('c6000000-0000-0000-0000-000000000031', 'Red flags requiring more urgent action include septal haematoma (same-day drainage), CSF rhinorrhoea, or visual disturbance (suggesting orbital involvement).', 2),
('c6000000-0000-0000-0000-000000000031', 'If manipulation is needed for deformity, this is typically performed within about 2 weeks of injury before the bones set.', 3),
('c6000000-0000-0000-0000-000000000032', 'Chronic rhinosinusitis is defined as symptoms (nasal blockage, discharge, facial pain/pressure, or reduced smell) lasting more than 12 weeks.', 1),
('c6000000-0000-0000-0000-000000000032', 'First-line management is a prolonged trial (at least 4-6 weeks) of intranasal corticosteroids combined with saline nasal irrigation.', 2),
('c6000000-0000-0000-0000-000000000032', 'ENT referral (with consideration of imaging and surgery) is reserved for cases failing adequate medical therapy or with red flag features suggesting an alternative diagnosis.', 3),
('c6000000-0000-0000-0000-000000000033', 'Rhinitis medicamentosa results from prolonged use (generally beyond 5-7 days) of topical decongestant sprays (e.g. oxymetazoline, xylometazoline), causing rebound vasodilation and worsening congestion.', 1),
('c6000000-0000-0000-0000-000000000033', 'Patients typically describe a cycle of brief relief followed by progressively worse congestion, prompting increased use of the spray.', 2),
('c6000000-0000-0000-0000-000000000033', 'Management involves stopping the decongestant spray (sometimes with a short corticosteroid course to ease withdrawal symptoms) and patient education on appropriate short-term use only.', 3),
('c6000000-0000-0000-0000-000000000034', 'Unilateral, foul-smelling nasal discharge in a child should always raise suspicion of a retained foreign body, even without a clear witnessed history of insertion.', 1),
('c6000000-0000-0000-0000-000000000034', 'Retained foreign bodies can cause secondary bacterial infection with purulent discharge; removal (rather than antibiotics alone) is the definitive treatment.', 2),
('c6000000-0000-0000-0000-000000000034', 'A preceding nosebleed or unwitnessed play with small objects is a useful clue prompting anterior rhinoscopy to look directly for a foreign body.', 3),
('c6000000-0000-0000-0000-000000000035', $x$Samter's triad (aspirin-exacerbated respiratory disease) comprises asthma, chronic rhinosinusitis with nasal polyps, and sensitivity to NSAIDs/aspirin causing acute bronchospasm and nasal symptoms.$x$, 1),
('c6000000-0000-0000-0000-000000000035', 'The reaction is due to dysregulation of the arachidonic acid/leukotriene pathway rather than classic IgE-mediated allergy, but can still cause severe bronchospasm.', 2),
('c6000000-0000-0000-0000-000000000035', $x$Management includes strict avoidance of NSAIDs/aspirin, treatment of the underlying rhinosinusitis/asthma, and clear documentation/alerting of the sensitivity in the patient's records.$x$, 3),
('c6000000-0000-0000-0000-000000000036', 'Hoarseness persisting beyond 3 weeks (especially with risk factors such as smoking and alcohol, or red flags like weight loss/dysphagia) warrants urgent 2-week wait referral to exclude laryngeal cancer.', 1),
('c6000000-0000-0000-0000-000000000036', 'Laryngoscopy (direct or flexible nasendoscopy) is required to directly visualise the vocal cords and larynx for a suspicious lesion.', 2),
('c6000000-0000-0000-0000-000000000036', 'Smoking and alcohol are the two major synergistic risk factors for head and neck squamous cell carcinoma, including laryngeal cancer.', 3),
('c6000000-0000-0000-0000-000000000037', 'A persistent (>3 weeks), firm, fixed, enlarging cervical lymph node in a patient with smoking/alcohol risk factors is a red flag for metastatic head and neck cancer and warrants urgent 2-week wait referral.', 1),
('c6000000-0000-0000-0000-000000000037', 'Referred otalgia (ear pain without ear pathology) and dysphagia can indicate a primary tumour in the oropharynx, hypopharynx, or larynx.', 2),
('c6000000-0000-0000-0000-000000000037', 'Open excisional biopsy of a suspicious neck node in primary care should be avoided; specialist assessment (including fine needle aspiration cytology and search for a primary lesion) is the appropriate pathway.', 3),
('c6000000-0000-0000-0000-000000000038', 'Most acute tonsillitis is viral and self-limiting; symptomatic management (analgesia, fluids) is first-line, with clinical scoring systems (Centor, FeverPAIN) guiding antibiotic decisions for likely bacterial cases.', 1),
('c6000000-0000-0000-0000-000000000038', 'Red flags suggesting a complication (peritonsillar abscess, airway compromise) include trismus, drooling, stridor, or unilateral swelling with uvular deviation, none of which are present here.', 2),
('c6000000-0000-0000-0000-000000000038', 'Tonsillectomy is reserved for recurrent tonsillitis meeting specific frequency/severity criteria, not for a single acute episode.', 3),
('c6000000-0000-0000-0000-000000000039', 'Infectious mononucleosis (EBV) classically causes severe exudative tonsillitis, fever, fatigue, posterior cervical lymphadenopathy, and splenomegaly, often in adolescents/young adults.', 1),
('c6000000-0000-0000-0000-000000000039', 'A widespread rash after amoxicillin/ampicillin administration is a well-known phenomenon in glandular fever and does not necessarily indicate true penicillin allergy.', 2),
('c6000000-0000-0000-0000-000000000039', 'Amoxicillin should be avoided when infectious mononucleosis is suspected, and patients should be advised to avoid contact sports for several weeks due to splenomegaly and rupture risk.', 3),
('c6000000-0000-0000-0000-000000000040', 'Thyroglossal duct cysts are midline neck swellings that classically move upward with swallowing and tongue protrusion, due to their embryological connection to the base of the tongue via the foramen caecum.', 1),
('c6000000-0000-0000-0000-000000000040', 'They can become recurrently infected, and definitive treatment is surgical excision (Sistrunk procedure), which removes the cyst tract along with the central portion of the hyoid bone to reduce recurrence.', 2),
('c6000000-0000-0000-0000-000000000040', 'Distinguish from branchial cysts (lateral, anterior to sternocleidomastoid) and cystic hygromas (posterior triangle, transilluminate).', 3),
('c6000000-0000-0000-0000-000000000041', 'Hoarseness following vocal overuse in a young, low-risk (non-smoker, no red flags) patient is often due to benign causes such as vocal cord nodules, but persistence beyond 3-6 weeks still warrants laryngoscopic assessment.', 1),
('c6000000-0000-0000-0000-000000000041', 'Red flags that would prompt more urgent referral include significant smoking/alcohol history, dysphagia, weight loss, stridor, or a neck lump.', 2),
('c6000000-0000-0000-0000-000000000041', 'Voice rest and speech and language therapy (voice therapy) are first-line for benign vocal cord nodules once malignancy has been excluded or is deemed unlikely.', 3),
('c6000000-0000-0000-0000-000000000042', 'Pleomorphic adenoma is the most common benign salivary gland tumour, typically presenting as a slow-growing, painless, mobile parotid mass without facial nerve involvement.', 1),
('c6000000-0000-0000-0000-000000000042', 'Facial nerve weakness, pain, rapid growth, or skin fixation associated with a parotid mass are red flags suggesting malignancy and should prompt more urgent specialist assessment.', 2),
('c6000000-0000-0000-0000-000000000042', 'Management of pleomorphic adenoma is surgical excision, as there is a risk of malignant transformation (carcinoma ex pleomorphic adenoma) if left untreated long-term, and biopsy/fine needle aspiration helps guide pre-operative planning.', 3),
('c6000000-0000-0000-0000-000000000043', $x$Sialolithiasis (salivary gland stones) most commonly affects the submandibular gland due to its duct anatomy, causing pain and swelling precipitated by eating ('mealtime syndrome').$x$, 1),
('c6000000-0000-0000-0000-000000000043', 'A palpable hard mass along the duct in the floor of the mouth supports the diagnosis; imaging (ultrasound or sialography) and ENT referral help confirm and guide management (stone removal, sialendoscopy, or gland excision if recurrent).', 2),
('c6000000-0000-0000-0000-000000000043', $x$Distinguish from Sjogren's syndrome (chronic dryness, gradual bilateral swelling) and from tumours (painless, gradually enlarging mass without meal-related triggers).$x$, 3),
('c6000000-0000-0000-0000-000000000044', $x$Pharyngeal pouch (Zenker's diverticulum) classically presents with dysphagia, regurgitation of undigested food, halitosis, and gurgling noises in the neck on swallowing, typically in older adults.$x$, 1),
('c6000000-0000-0000-0000-000000000044', 'Progressive dysphagia with weight loss in an older adult is a red flag requiring urgent investigation (barium swallow and/or upper GI endoscopy) to exclude oesophageal or pharyngeal malignancy alongside assessing for a pouch.', 2),
('c6000000-0000-0000-0000-000000000044', 'Endoscopic instrumentation should be performed cautiously in suspected pharyngeal pouch due to the risk of perforation if the pouch is inadvertently entered instead of the true oesophageal lumen.', 3),
('c6000000-0000-0000-0000-000000000045', 'Globus pharyngeus is a persistent sensation of a lump in the throat without true dysphagia, often relieved by eating/drinking and associated with anxiety, and is a diagnosis of exclusion.', 1),
('c6000000-0000-0000-0000-000000000045', 'True dysphagia (difficulty actually swallowing solids or liquids), weight loss, or a palpable mass are red flags that should prompt further investigation to exclude organic pathology before diagnosing globus pharyngeus.', 2),
('c6000000-0000-0000-0000-000000000045', 'Management includes reassurance, addressing underlying anxiety, and referral for laryngoscopy/further investigation if any atypical or red flag features are present.', 3),
('c6000000-0000-0000-0000-000000000046', 'Suppurative cervical lymphadenitis presents with a rapidly enlarging, tender, fluctuant neck mass with systemic illness, often following a preceding upper respiratory infection, and can be confirmed with ultrasound.', 1),
('c6000000-0000-0000-0000-000000000046', 'Initial management is admission for IV antibiotics, with incision and drainage reserved for collections that fail to respond or continue to enlarge.', 2),
('c6000000-0000-0000-0000-000000000046', 'Signs of airway compromise (stridor, significant trismus, drooling) or failure to improve should prompt escalation and more urgent surgical/ENT involvement.', 3),
('c6000000-0000-0000-0000-000000000047', 'Simple cerumen (ear wax) impaction causing conductive hearing loss is managed with wax-softening drops (e.g. olive oil, sodium bicarbonate) first-line, with irrigation or microsuction if needed.', 1),
('c6000000-0000-0000-0000-000000000047', 'Cotton bud use is a common cause of wax impaction by pushing wax deeper into the canal and should be discouraged.', 2),
('c6000000-0000-0000-0000-000000000047', 'Irrigation is avoided if there is a history of perforation, previous ear surgery, or active infection; microsuction is preferred in these situations.', 3),
('c6000000-0000-0000-0000-000000000048', 'CSF rhinorrhoea should be suspected with clear, watery unilateral nasal discharge after head trauma, especially if it worsens on leaning forward or straining.', 1),
('c6000000-0000-0000-0000-000000000048', 'Nasal packing is avoided in suspected CSF leaks due to infection risk; urgent neurosurgical/ENT referral and CT imaging are required.', 2),
('c6000000-0000-0000-0000-000000000048', 'Patients with a confirmed or suspected CSF leak need monitoring for signs of meningitis and may require prophylactic measures or surgical repair depending on the size and persistence of the leak.', 3),
('c6000000-0000-0000-0000-000000000049', 'A deviated nasal septum causes fixed, often unilateral, structural nasal obstruction, frequently following previous nasal trauma, and is diagnosed on anterior rhinoscopy/nasal endoscopy.', 1),
('c6000000-0000-0000-0000-000000000049', 'Unlike allergic or infective causes, there is typically no significant discharge, itching, or mucosal inflammation, though a deviated septum can predispose to secondary sinusitis.', 2),
('c6000000-0000-0000-0000-000000000049', 'Management for significant symptomatic cases refractory to conservative measures is surgical correction (septoplasty).', 3),
('c6000000-0000-0000-0000-000000000050', 'A goitre (diffuse thyroid enlargement) that moves on swallowing, with normal thyroid function, should be further assessed with thyroid ultrasound to characterise the gland and detect any discrete nodules.', 1),
('c6000000-0000-0000-0000-000000000050', 'Discrete or dominant nodules found on ultrasound may need fine needle aspiration cytology to exclude malignancy, particularly if there are red flag features (rapid growth, hoarseness, hard fixed nodule, lymphadenopathy).', 2),
('c6000000-0000-0000-0000-000000000050', 'Thyroid function tests (TSH, free T4) are essential to determine whether a goitre is associated with hypo-, hyper-, or euthyroidism, guiding further management alongside imaging.', 3);
